import React from 'react';
import { CONTACT, PROFILE } from '@/lib/profile';
import { SITE_URL } from '@/lib/seo';

/**
 * Person structured data, on the About page only.
 *
 * Scoped hard to what the record actually supports. Deliberately absent:
 *
 *  - `jobTitle` and `worksFor`. The site carried three different Alvolo titles
 *    and the engagement is dated closed; asserting a current title in machine-
 *    readable form would be the same unverified claim in a more durable format.
 *  - `award`, `aggregateRating`, `review`. Nothing to cite.
 *  - `email`. Publishing it in JSON-LD adds nothing a crawler needs and hands
 *    it to scrapers in a convenient shape; the page shows it to people.
 *
 * `alumniOf` is included because two completed degrees are stated with dates on
 * the same page, and `knowsLanguage` because the language table is on it too.
 */
export default function PersonSchema({ path }: { path: string }) {
  const data = {
    '@context': 'https://schema.org',
    '@type': 'Person',
    name: PROFILE.name,
    url: `${SITE_URL}${path}`,
    address: {
      '@type': 'PostalAddress',
      addressLocality: PROFILE.city,
      addressCountry: 'IT',
    },
    alumniOf: {
      '@type': 'CollegeOrUniversity',
      name: 'Bocconi University',
    },
    knowsLanguage: ['en', 'it', 'tr'],
    sameAs: [CONTACT.linkedin.url, CONTACT.github.url],
  };

  return (
    <script
      type="application/ld+json"
      // Serialised from a literal built above; no user input reaches it.
      dangerouslySetInnerHTML={{ __html: JSON.stringify(data) }}
    />
  );
}

import React from 'react';

/**
 * A horizontally scrollable region a keyboard can actually reach.
 *
 * Dense content — a wide figure, a table, a block of source rows — is allowed
 * to scroll inside its own bounds so the page body never does. But a scroll
 * container that is not focusable strands its overflow for anyone not using a
 * pointer, which axe reports as `scrollable-region-focusable` and which is a
 * real barrier rather than a technicality.
 *
 * `tabIndex={0}` makes it focusable so arrow keys scroll it; `role="group"`
 * plus a label means a screen reader announces what the region contains rather
 * than dropping the reader into an unnamed box.
 */
export default function ScrollRegion({
  label,
  className = '',
  children,
}: {
  /** What the region contains. It is announced, so it must be meaningful. */
  label: string;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <div className={`scroll-x ${className}`} data-scroll-region tabIndex={0} role="group" aria-label={label}>
      {children}
    </div>
  );
}

