import Link from "next/link";
import type { Locale } from "@/lib/translations";
import { getLibraryUI } from "@/lib/content/library-ui";
import { PROFILE } from "@/lib/profile";
import { getShelfBooks } from "../shelf/volumes";
import { getShelfUI } from "../shelf/shelf-ui";
import ShelfLauncher from "../shelf/ShelfLauncher";
import Footer from "@/app/sections/Footer";
import WorldExperience from "./world/WorldExperience";
import SubjectArt from "./SubjectArt";
import "../shelf/catalogue.css";
import "./experience.css";

/** Original content, rebuilt as a spatial index and readable narrative chapters. */
export default function ExperienceHome({ locale }: { locale: Locale }) {
  const copy = getLibraryUI(locale),
    shelf = getShelfUI(locale),
    books = getShelfBooks(locale);
  return (
    <>
      <main className="atlas-page">
        <WorldExperience
          locale={locale}
          subjects={books}
          copy={copy}
          identity={shelf.identity}
        />
        <section
          className="atlas-context"
          aria-labelledby="catalogue-title"
          id="catalogue"
          data-story-section="editorial"
        >
          <div className="atlas-section-label">
            <span>01 /</span>
            <p>{copy.collection}</p>
          </div>
          <div>
            <p className="atlas-intro">{copy.intro}</p>
            <div className="atlas-context-bottom">
              <h2 id="catalogue-title">{copy.directory}</h2>
              <p>{copy.collectionNote}</p>
              <Link href={`/${locale}/front-matter`} className="atlas-link">
                {copy.approach}
                <span aria-hidden="true">↗</span>
              </Link>
            </div>
          </div>
        </section>
        <section className="atlas-services" aria-label={copy.service}>
          {books.slice(0, 4).map((book, index) => (
            <article
              className="atlas-service"
              data-story-section="editorial"
              data-volume={index}
              id={`subject-${book.id}`}
              key={book.id}
              aria-labelledby={`catalogue-${book.id}`}
            >
              <div className="atlas-service-top">
                <span className="atlas-number">{book.roman}</span>
                <p className="atlas-meta">
                  {copy.service} <span aria-hidden="true">/</span>{" "}
                  {book.discipline}
                </p>
              </div>
              <div className="atlas-service-body">
                <div className="atlas-service-copy">
                  <h3 id={`catalogue-${book.id}`}>
                    <Link href={`/${locale}${book.href}`} prefetch={false}>
                      {book.title}
                      <span aria-hidden="true">↗</span>
                    </Link>
                  </h3>
                  <p>{book.note}</p>
                  <div className="atlas-deliverable">
                    <span className="atlas-meta">{copy.takeaway}</span>
                    <p>{book.format}</p>
                  </div>
                  {book.id === "cross-border" && (
                    <p className="atlas-boundary">{copy.boundary}</p>
                  )}
                  <Link
                    href={`/${locale}${book.href}`}
                    prefetch={false}
                    className="atlas-link"
                    aria-label={`${copy.read}: ${book.title}`}
                  >
                    {copy.read}
                    <span aria-hidden="true">↗</span>
                  </Link>
                </div>
                <div className="atlas-service-plate">
                  <SubjectArt index={index} />
                  <span className="atlas-plate-number" aria-hidden="true">
                    0{index + 1}
                  </span>
                </div>
              </div>
            </article>
          ))}
        </section>
        <section className="atlas-research" aria-label={copy.research}>
          <div className="atlas-section-label">
            <span>02 /</span>
            <p>{copy.research}</p>
            <span className="atlas-label-right">V — VII</span>
          </div>
          {books.slice(4).map((book, i) => (
            <article
              className={`atlas-case atlas-case-${i}`}
              data-story-section="editorial"
              data-volume={i + 4}
              id={`subject-${book.id}`}
              key={book.id}
              aria-labelledby={`catalogue-${book.id}`}
            >
              <Link
                className="atlas-case-art"
                href={`/${locale}${book.href}`}
                prefetch={false}
                aria-label={`${copy.read}: ${book.title}`}
              >
                <SubjectArt index={i + 4} />
                <span className="atlas-case-roman" aria-hidden="true">
                  {book.roman}
                </span>
                <span className="atlas-case-open" aria-hidden="true">
                  ↗
                </span>
              </Link>
              <div className="atlas-case-heading">
                <p className="atlas-meta">
                  {i === 2 ? copy.synthetic : copy.research} / {book.discipline}
                </p>
                <h3 id={`catalogue-${book.id}`}>
                  <Link href={`/${locale}${book.href}`} prefetch={false}>
                    {book.title}
                  </Link>
                </h3>
              </div>
              <div className="atlas-case-description">
                <p>{book.note}</p>
                <div className="atlas-deliverable">
                  <span className="atlas-meta">{copy.takeaway}</span>
                  <p>{book.format}</p>
                </div>
                <Link
                  className="atlas-link"
                  href={`/${locale}${book.href}`}
                  prefetch={false}
                >
                  {copy.read}
                  <span aria-hidden="true">↗</span>
                </Link>
              </div>
            </article>
          ))}
        </section>
        <section
          className="atlas-explore"
          data-story-section="explore"
          aria-labelledby="library-invitation-title"
        >
          <div className="atlas-section-label">
            <span>03 /</span>
            <p>{copy.collection}</p>
          </div>
          <div className="atlas-bindings" aria-hidden="true">
            {books.map((book, i) => (
              <div
                key={book.id}
                style={{
                  background: book.color,
                  transform: `rotate(${(i - 3) * 5}deg) translateY(${Math.abs(i - 3) * 12}px)`,
                }}
              >
                <span>{book.roman}</span>
                <span>{book.title}</span>
              </div>
            ))}
          </div>
          <div className="atlas-explore-bottom">
            <h2 id="library-invitation-title">{copy.shelfTitle}</h2>
            <div>
              <p>{copy.shelfNote}</p>
              <ShelfLauncher locale={locale} copy={copy} />
              <noscript>
                <style>{"[data-enter-shelf]{display:none}"}</style>
              </noscript>
            </div>
          </div>
        </section>
        <section className="atlas-conversation" data-story-section="contact" id="conversation">
          <div className="atlas-section-label">
            <span>04 /</span>
            <p>{PROFILE.name}</p>
          </div>
          <Link className="atlas-contact-title" href={`/${locale}/contact`}>
            {copy.contact}
            <span aria-hidden="true">↗</span>
          </Link>
          <div className="atlas-endnote">
            <p>{shelf.fallbackNote}</p>
            <Link className="atlas-link" href={`/${locale}/front-matter`}>
              {copy.approach}
              <span aria-hidden="true">↗</span>
            </Link>
          </div>
        </section>
      </main>
      <Footer locale={locale} />
    </>
  );
}

"use client";
import { useEffect, useId, useRef, useState } from "react";
import Link from "next/link";
import Image from "next/image";
import { usePathname } from "next/navigation";
import type { Locale } from "@/lib/translations";
import type { UIStrings } from "@/lib/content/ui";
import { CONTACT, PROFILE } from "@/lib/profile";
import { experience } from './director/experience-director';

type Props = {
  locale: Locale;
  nav: UIStrings["nav"];
  about: string;
  books: {
    id: string;
    href: string;
    roman: string;
    title: string;
    discipline: string;
  }[];
};
const languages: Record<Locale, string> = {
  en: "English",
  tr: "Türkçe",
  it: "Italiano",
};
export default function ExperienceNavigation({
  locale,
  nav,
  about,
  books,
}: Props) {
  const pathname = usePathname(),
    dialog = useRef<HTMLDialogElement>(null),
    trigger = useRef<HTMLButtonElement>(null),
    id = useId();
  const [open, setOpen] = useState(false);
  const suffix = pathname.replace(/^\/(en|tr|it)(?=\/|$)/, "");
  useEffect(() => {
    setOpen(false);
  }, [pathname]);
  useEffect(() => {
    if (!open) return;
    const modal = dialog.current,
      previous = document.body.style.overflow,
      returnTo = trigger.current;
    document.body.style.overflow = "hidden";
    const unlock = experience.lock('navigation');
    modal?.showModal();
    const containFocus = (event: KeyboardEvent) => {
      if (event.key !== "Tab" || !modal) return;
      const items = Array.from(
        modal.querySelectorAll<HTMLElement>("a[href],button:not([disabled])"),
      ).filter((e) => e.getClientRects().length > 0);
      const first = items[0],
        last = items[items.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last?.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first?.focus();
      }
    };
    modal?.addEventListener("keydown", containFocus);
    return () => {
      modal?.removeEventListener("keydown", containFocus);
      modal?.close();
      document.body.style.overflow = previous;
      unlock();
      returnTo?.focus({ preventScroll: true });
    };
  }, [open]);
  const link = (path: string, label: string) => (
    <Link
      href={`/${locale}${path}`}
      prefetch={false}
      onClick={() => setOpen(false)}
      aria-current={suffix === path ? "page" : undefined}
    >
      {label}
      <span aria-hidden="true">↗</span>
    </Link>
  );
  return (
    <>
      <nav className="site-nav atlas-nav" aria-label={nav.mainLabel}>
        <Link
          className="atlas-brand"
          href={`/${locale}`}
          prefetch={false}
          aria-label={PROFILE.name}
        >
          <Image src="/logo-mark.webp" width={28} height={28} alt="" priority />
          <span>{PROFILE.name}</span>
        </Link>
        <div className="atlas-nav-links">
          {link("/front-matter", nav.frontMatter)}
          {link("/chapters", about)}
          {link("/contact", nav.contact)}
        </div>
        <div className="atlas-nav-tools">
          <div
            className="atlas-languages"
            role="group"
            aria-label={nav.language}
          >
            {(["en", "tr", "it"] as Locale[]).map((l) => (
              <Link
                key={l}
                href={`/${l}${suffix}`}
                prefetch={false}
                hrefLang={l}
                lang={l}
                aria-label={languages[l]}
                aria-current={l === locale ? "true" : undefined}
              >
                {l.toUpperCase()}
              </Link>
            ))}
          </div>
          <button
            ref={trigger}
            onClick={() => setOpen(true)}
            aria-expanded={open}
            aria-controls={id}
            aria-label={nav.menu}
            className="atlas-menu-trigger"
          >
            <span>{nav.volumes}</span>
            <span aria-hidden="true" className="atlas-menu-symbol">
              ＋
            </span>
          </button>
        </div>
      </nav>
      <dialog
        className="atlas-menu nav-mobile"
        ref={dialog}
        id={id}
        aria-label={nav.mainLabel}
        onCancel={() => setOpen(false)}
      >
        <div className="atlas-menu-top">
          <Link href={`/${locale}`} prefetch={false} onClick={() => setOpen(false)}>
            {PROFILE.name}
          </Link>
          <button onClick={() => setOpen(false)} aria-label={nav.closeMenu}>
            {nav.closeMenu}
            <span aria-hidden="true">×</span>
          </button>
        </div>
        <div className="atlas-menu-body">
          <nav className="atlas-menu-primary" aria-label={nav.mainLabel}>
            {link("", nav.shelf)}
            {link("/front-matter", nav.frontMatter)}
            {link("/chapters", about)}
            {link("/contact", nav.contact)}
          </nav>
          <nav className="atlas-menu-volumes" aria-label={nav.volumes}>
            <p>{nav.volumes} / 07</p>
            {books.map((book) => (
              <Link
                key={book.id}
                href={`/${locale}${book.href}`}
                onClick={() => setOpen(false)}
                prefetch={false}
              >
                <span>{book.roman}</span>
                <span>
                  <strong>{book.title}</strong>
                  <small>{book.discipline}</small>
                </span>
                <span aria-hidden="true">↗</span>
              </Link>
            ))}
          </nav>
        </div>
        <div className="atlas-menu-bottom">
          <div
            className="atlas-languages"
            role="group"
            aria-label={nav.language}
          >
            {(["en", "tr", "it"] as Locale[]).map((l) => (
              <Link
                key={l}
                onClick={() => setOpen(false)}
                href={`/${l}${suffix}`}
                prefetch={false}
                hrefLang={l}
                lang={l}
                aria-current={l === locale ? "true" : undefined}
              >
                {languages[l]}
              </Link>
            ))}
          </div>
          <div>
            <a href={CONTACT.linkedin.url} target="_blank" rel="noreferrer">
              LinkedIn ↗
            </a>
            <a href={CONTACT.github.url} target="_blank" rel="noreferrer">
              GitHub ↗
            </a>
          </div>
        </div>
      </dialog>
    </>
  );
}

