  max-width: none;
  margin-top: 0;
  padding-top: 0;
}
.composer-mode {
  border-bottom: 1px solid #eae8dd36;
  gap: 24px;
  margin-bottom: 28px;
}
.composer-mode button {
  border: 0;
  border-radius: 0;
  padding: 12px 0 18px;
  color: #b3baa9;
}
.composer-mode button[aria-pressed="true"] {
  color: #d4de95;
  background: transparent;
  border-bottom: 2px solid #d4de95;
}
.conversation-fields > input,
.conversation-fields > textarea,
.conversation-review > textarea,
.composer-identity input,
.composer-identity select {
  background: #202820;
  border-color: #8f9e7e;
  border-radius: 0;
  color: #eae8dd;
  font-family: var(--font-ui);
  font-size: 16px;
}
.conversation-fields > textarea {
  min-height: 240px;
  padding: 20px;
}
.conversation-fields input::placeholder,
.conversation-fields textarea::placeholder {
  color: #b3baa9;
}
.composer-options summary,
.composer-preview summary,
.contact-optional-scene > button,
.conversation-alternatives a,
.conversation-alternatives button,
.conversation-back {
  color: #d4de95;
}
.conversation-primary {
  border-radius: 0;
  background: #d4de95;
  color: #181c18;
  border-color: #d4de95;
}
.conversation-primary:hover {
  background: #e2ebb2;
  transform: none;
}
.conversation-secondary {
  border-radius: 0;
  color: #eae8dd;
  border-color: #8f9e7e;
}
.conversation-hint,
.conversation-small,
.conversation-privacy,
.composer-identity label span {
  color: #b3baa9;
}
.conversation-privacy,
.contact-optional-scene {
  border-color: #eae8dd36;
}
.conversation-small,
.conversation-privacy {
  font-size: 12px;
  line-height: 1.7;
}
.conversation-panel h2 {
  font: 400 clamp(28px, 3vw, 44px) / 1.15 var(--font-ui);
  letter-spacing: -0.035em;
}
.conversation-option {
  border-radius: 0;
  border-color: #8f9e7e;
}
.conversation-option:has(input:checked) {
  border-color: #d4de95;
  background: #d4de9510;
}
.conversation-progress li {
  color: #b3baa9;
}
.conversation-progress li[data-active="true"],
.conversation-progress li[data-complete="true"] {
  color: #d4de95;
  border-color: #d4de95;
}
.contact-career-link {
  grid-column: 1;
  margin-top: 20px;
  color: #d4de95;
}
@media (max-width: 1000px) {
  .conversation-page {
    column-gap: 40px;
  }
  .conversation-intro h1 {
    font-size: 56px;
  }
  .conversation-delivery {
    flex-direction: column;
    align-items: stretch;
  }
  .chapters-hero h1 {
    font-size: 8vw;
  }
}
@media (max-width: 700px) {
  .chapters-page {
    padding-top: 104px;
  }
  .chapters-hero {
    display: flex;
    flex-direction: column;
    padding-bottom: 48px;
    gap: 35px;
  }
  .chapters-hero h1 {
    max-width: none;
    font-size: 57px;
  }
  .chapters-lede {
    font-size: 16px;
  }
  .chapters-portrait {
    position: relative;
    inset: auto;
    width: 72%;
    max-width: 350px;
    margin: 0 0 0 auto;
  }
  .chapters-portrait figcaption {
    display: flex;
  }
  .portrait-edition {
    display: block;
  }
  .chapters-portrait img {
    box-shadow: none;
  }
  .career-record {
    padding-block: 40px;
  }
  .career-record-grid {
    display: block;
  }
  .career-record-grid > section + section {
    margin-top: 35px;
  }
  .career-record header p:not(.chapters-eyebrow) {
    font-size: 16px;
  }
  .chapters-next {
    padding: 60px 0;
  }
  .conversation-page {
    display: block;
    padding-top: 105px;
    padding-bottom: 45px;
  }
  .conversation-intro h1 {
    font-size: 51px;
  }
  .conversation-direct {
    margin-top: 32px;
    margin-bottom: 32px;
  }
  .conversation-fields > textarea {
    min-height: 200px;
  }
  .contact-career-link {
    margin-top: 32px;
  }
}
@media print {
  .chapters-page {
    padding: 0;
  }
  .career-record {
    margin: 0;
    padding: 20px 0;
  }
  .career-record h2 {
    font-size: 28px;
  }
  .chapters-hero h1 {
    font-size: 36px;
  }
}

