src/app/components/experience/system.css:
/* Shared house tokens. Legacy opt-in book/shelf retain their own scoped artwork. */
:root {
  --background: #181c18;
  --foreground: #eae8dd;
  --muted: #b3baa9;
  --accent: #d4de95;
  --line: #eae8dd36;
  --surface: #202820;
  --c-ground: 24 28 24;
  --c-panel: 32 40 32;
  --c-panel-alt: 28 33 28;
  --c-panel-raised: 43 51 40;
  --c-text: 234 232 221;
  --c-text-2: 220 222 209;
  --c-text-3: 195 202 184;
  --c-muted: 179 186 169;
  --c-muted-light: 163 174 151;
  --c-brass: 212 222 149;
  --c-brass-hi: 226 235 178;
  --c-brass-hover: 225 235 168;
  --c-hairline: 63 71 57;
  --c-hairline-strong: 86 98 77;
  --c-hairline-control: 143 158 126;
  --font-display: var(--font-sans), Arial, sans-serif;
  --font-body: var(--font-sans), Arial, sans-serif;
  --font-text: var(--font-body);
  --space-xs: 8px;
  --space-sm: 16px;
  --space-md: 24px;
  --space-lg: 40px;
  --space-xl: 64px;
  --space-2xl: 100px;
  --page-padding: clamp(22px, 4vw, 80px);
  --grid-gap: clamp(20px, 3vw, 56px);
  --ease-primary: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
  --duration-fast: 160ms;
  --duration-medium: 420ms;
  --duration-slow: 640ms;
}
html {
  scroll-behavior: auto;
  scroll-padding-top: 90px;
}
/* Hidden overflow creates a second scroll container and defeats sticky scenes. */
html,
body.overflow-x-hidden {
  overflow-x: clip;
}
:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 5px;
}
.atlas-nav {
  position: fixed;
  z-index: 50;
  inset: 0 0 auto;
  height: 68px;
  padding: 0 var(--page-padding);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  background: #181c18;
  color: #eae8dd;
  border-bottom: 1px solid #eae8dd26;
  font: 400 12px/1.4 var(--font-ui);
}
.atlas-brand {
  display: flex;
  gap: 12px;
  align-items: center;
  min-height: 44px;
  white-space: nowrap;
}
.atlas-brand img {
  width: 28px;
  height: 28px;
}
.atlas-nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}
.atlas-nav-links a {
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.atlas-nav-links a span {
  color: #b3baa9;
}
.atlas-nav-links a[aria-current="page"] {
  color: #d4de95;
}
.atlas-nav-tools {
  display: flex;
  align-items: center;
  gap: 28px;
}
.atlas-languages {
  display: flex;
  gap: 12px;
  align-items: center;
}
.atlas-languages a {
  min-height: 44px;
  min-width: 28px;
  display: inline-flex;
  justify-content: center;
  align-items: center;
  color: #b3baa9;
}
.atlas-languages a[aria-current="true"] {
  color: #d4de95;
  text-decoration: underline;
  text-underline-offset: 6px;
}
.atlas-menu-trigger {
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 20px;
  border-left: 1px solid #eae8dd36;
  padding-left: 25px;
}
.atlas-menu-symbol {
  font-size: 26px;
  line-height: 1;
}
.atlas-nav a:hover,
.atlas-nav button:hover {
  color: #d4de95;
}
.atlas-menu {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100dvh;
  max-width: none;
  max-height: none;
  margin: 0;
  padding: 0 var(--page-padding);
  background: #181c18;
  color: #eae8dd;
  border: 0;
  overflow-y: auto;
}
.atlas-menu::backdrop {
  background: #181c18;
}
.atlas-menu[open] {
  animation: menu-enter var(--duration-medium) var(--ease-primary) both;
}
.atlas-menu-top {
  display: flex;
  min-height: 80px;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  border-bottom: 1px solid #eae8dd36;
  font-size: 13px;
}
.atlas-menu-top button {
  display: flex;
  align-items: center;
  gap: 24px;
  min-height: 44px;
}
.atlas-menu-top button span {
  font-size: 32px;
}
.atlas-menu-body {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9vw;
  padding-block: 55px;
}
.atlas-menu-primary {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.atlas-menu-primary a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 70px;
  padding-block: 10px;
  font: 400 clamp(30px, 4.2vw, 78px) / 1.1 var(--font-ui);
  letter-spacing: -0.055em;
}
.atlas-menu-primary a span {
  font-size: 0.7em;
  color: #d4de95;
}
.atlas-menu-volumes > p {
  font-size: 12px;
  color: #b3baa9;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.atlas-menu-volumes > a {
  display: grid;
  grid-template-columns: 28px 1fr 20px;
  gap: 20px;
  padding: 15px 0;
  border-top: 1px solid #eae8dd36;
}
.atlas-menu-volumes > a > span:first-child {
  color: #d4de95;
  font:
    italic 400 22px "Instrument Serif",
    Georgia,
    serif;
}
.atlas-menu-volumes strong {
  display: block;
  font-size: 21px;
  font-weight: 400;
  letter-spacing: -0.025em;
}
.atlas-menu-volumes small {
  display: block;
  font-size: 11px;
  color: #b3baa9;
  margin-top: 5px;
}
.atlas-menu a:hover {
  color: #d4de95;
}
.atlas-menu-bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  border-top: 1px solid #eae8dd36;
  padding-block: 20px;
  font-size: 12px;
}
.atlas-menu-bottom > div {
  display: flex;
  gap: 25px;
}
.atlas-menu-bottom a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
}
.experience-route {
  animation: route-enter 320ms var(--ease-primary) both;
}
.experience-footer {
  background: #141914 !important;
}
.experience-footer > div {
  max-width: none;
  padding: 55px var(--page-padding) 25px;
}
.experience-footer .footer-signature {
  font: 500 clamp(44px, 8.9vw, 180px) / 1 var(--font-ui);
  letter-spacing: -0.07em;
  border-bottom: 1px solid #eae8dd36;
  padding-bottom: 40px;
  text-wrap: nowrap;
}
.experience-footer a {
  min-height: 44px;
}
@keyframes route-enter {
  from {
    opacity: 0.45;
  }
  to {
    opacity: 1;
  }
}
@keyframes menu-enter {
  from {
    opacity: 0;
    clip-path: inset(0 0 100% 0);
  }
  to {
    opacity: 1;
    clip-path: inset(0);
  }
}
@media (max-width: 1100px) {
  .atlas-nav-links {
    gap: 18px;
  }
  .atlas-nav-tools {
    gap: 16px;
  }
  .atlas-menu-trigger > span:first-child {
    display: none;
  }
  .atlas-menu-trigger {
    padding-left: 18px;
  }
}
@media (max-width: 800px) {
  .atlas-menu[open] {
    animation: route-enter 160ms var(--ease-primary) both;
  }
  .atlas-nav-links {
    display: none;
  }
  .atlas-brand {
    font-size: 11px;
    gap: 8px;
  }
  .atlas-nav {
    gap: 12px;
  }
  .atlas-nav .atlas-languages {
    gap: 2px;
    font-size: 10px;
  }
  .atlas-menu-body {
    grid-template-columns: 1fr;
    gap: 40px;
    padding-block: 25px;
  }
  .atlas-menu-primary a {
    font-size: 36px;
    min-height: 56px;
    border-bottom: 1px solid #eae8dd26;
  }
  .atlas-menu-volumes strong {
    font-size: 20px;
  }
  .atlas-menu-bottom {
    flex-wrap: wrap;
  }
  .atlas-menu-top {
    min-height: 68px;
  }
  .experience-footer .footer-signature {
    font-size: 8.7vw;
    padding-bottom: 24px;
  }
  .experience-footer > div {
    padding-top: 35px;
  }
}
@media (max-width: 380px) {
  .atlas-brand img {
    display: none;
  }
  .atlas-nav {
    gap: 8px;
  }
  .atlas-menu-trigger {
    padding-left: 10px;
  }
  .atlas-nav-tools {
    gap: 10px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .experience-route,
  .atlas-menu[open] {
    animation: none;
  }
  html {
    scroll-behavior: auto !important;
  }
}
@media print {
  .atlas-nav,
  .atlas-menu,
  .experience-footer {
    display: none !important;
  }
  .experience-route {
    animation: none;
  }
}

