.world-chapter {
  position: relative;
  height: 175svh;
  background: #151e1a;
  color: #eae8dd;
}
.world-stage {
  position: sticky;
  top: 0;
  height: 100svh;
  min-height: 560px;
  isolation: isolate;
  overflow: hidden;
}
.world-canvas,
.world-placeholder,
.world-vignette {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}
.world-canvas {
