  opacity: 0;
  pointer-events: none;
}
.world-vignette {
  pointer-events: none;
  background: linear-gradient(
    180deg,
    #101914b3 0%,
    transparent 35%,
    transparent 65%,
    #101914e6 100%
  );
  z-index: 1;
}
.world-introduction {
  position: absolute;
  top: 110px;
  left: var(--page-padding);
  width: min(340px, 35vw);
  z-index: 2;
  pointer-events: none;
  opacity: calc(1 - var(--world-progress) * 1.3);
}
.world-eyebrow {
