    min-width: 0;
    min-height: 46px;
    font-size: 11px;
  }
  .world-browse {
    font-size: 11px;
    min-height: 46px;
    margin-top: 8px;
    justify-content: space-between;
  }
  .world-marker-title {
    display: none;
  }
  .world-marker > span:first-child {
    min-width: 27px;
    height: 27px;
    font-size: 10px;
  }
  .world-inspection {
    top: auto;
    bottom: 158px;
    left: 22px;
    right: 22px;
    width: auto;
    max-width: none;
    max-height: 43svh;
    animation: none;
  }
  .world-return {
    padding: 8px 16px;
    min-height: 44px;
  }
  .world-inspection-body {
    padding: 16px 20px;
  }
  .world-inspection h2 {
    font-size: 31px;
    margin: 10px 0 14px;
  }
  .world-inspection-body > p:not(.world-eyebrow) {
    font-size: 12px;
    line-height: 1.6;
  }
  .world-output {
    margin-top: 17px;
    padding-top: 14px;
  }
  .world-output > p {
    font-size: 11px;
  }
  .world-read {
    margin-top: 12px;
  }
  .world-paging {
    display: none;
  }
  .world-chapter:not([data-selected=""]) .world-guide {
    visibility: hidden;
  }
  .world-status {
    font-size: 10px;
    padding: 13px;
  }
  .world-status span {
    margin-left: 14px;
  }
}
@media (max-height: 650px) and (min-width: 701px) {
  .world-stage {
    min-height: 500px;
  }
  .world-inspection {
    top: 85px;
    bottom: 100px;
  }
  .world-introduction {
    top: 90px;
  }
  .world-introduction h1 {
    font-size: 24px;
  }
  .world-bottom {
    bottom: 16px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .world-chapter * {
    animation: none !important;
    transition: none !important;
  }
}
@media (max-height: 600px) {
  .world-stage {
    min-height: 360px;
  }
  .world-introduction {
    top: 85px;
    max-width: 230px;
  }
  .world-introduction h1 {
    font-size: 21px;
  }
  .world-identity,
  .world-coordinate {
    display: none;
  }
  .world-bottom {
    bottom: 12px;
  }
  .world-guide {
    margin-bottom: 6px;
  }
  .world-inspection {
    top: 80px;
    bottom: 82px;
    max-height: none;
  }
  .world-inspection h2 {
    font-size: 26px;
  }
  .world-inspection-body {
    padding: 15px 20px;
  }
}

