'use client';

import React, { useState } from 'react';
import { motion, useReducedMotion } from 'motion/react';
import { PieChart } from 'lucide-react';
import { PieChart as BklitPieChart } from '../ui/bklit/pie-chart';
import { PieSlice } from '../ui/bklit/pie-slice';
import { ASSETS, type Ticker, type AssetGroup } from '@/lib/optimizer/universe';
import type { Vec } from '@/lib/optimizer/linalg';
import { ASSET_COLORS, GROUP_LABELS, fmtPct, fmtSignedPct } from './format';
import { PanelTitle } from './primitives';

export default function AllocationChart({ weights, mu, prior }: { weights: Vec; mu: Vec; prior: Vec }) {
  const [hover, setHover] = useState<Ticker | null>(null);
  const reduced = useReducedMotion();

  const rows = ASSETS.map((a, i) => ({ asset: a, w: weights[i], mu: mu[i], prior: prior[i] })).sort((a, b) => b.w - a.w);
  // Stable slice order avoids morphing one asset into another when weights reorder.
  const slices = ASSETS.map((asset, i) => ({ label: asset.ticker, value: weights[i], color: ASSET_COLORS[asset.ticker] }));
  const hoveredIndex = hover ? ASSETS.findIndex(asset => asset.ticker === hover) : null;
  const selected = rows.find(row => row.asset.ticker === hover);
  const groups = (['equity', 'rates', 'real'] as AssetGroup[]).map((g) => ({
    id: g,
    label: GROUP_LABELS[g],
    total: rows.filter((r) => r.asset.group === g).reduce((s, r) => s + r.w, 0),
  }));

  return (
    <div>
      <PanelTitle icon={PieChart} title="Asset Allocation · w*" hint="0 ≤ wᵢ ≤ 40% · Σw = 1" />
      <div className="p-4">
        <div className="mb-4 flex flex-wrap items-center justify-center gap-5">
          <div className="relative" role="img" aria-label="Portfolio allocation donut; exact weights in the table below">
            <BklitPieChart data={slices} size={168} innerRadius={54} padAngle={0.025} cornerRadius={3}
              hoveredIndex={hoveredIndex} onHoverChange={index => setHover(index === null ? null : ASSETS[index].ticker)}
              hoverOffset={reduced ? 0 : 4} enterStaggerScale={0} geometryScrubbing={!!reduced}>
              {!reduced && slices.map((slice, index) => <PieSlice key={slice.label} index={index} animate={!reduced} showGlow={false} hoverEffect={reduced ? 'none' : 'translate'} />)}
            </BklitPieChart>
            <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center font-mono">
              <span className="text-lg tabular-nums text-charcoal">{selected ? fmtPct(selected.w) : '100%'}</span>
              <span className="text-[10px] uppercase tracking-wider text-muted">{selected ? selected.asset.ticker : 'Allocated'}</span>
            </div>
          </div>
          <div className="space-y-2 font-mono text-xs text-muted">
            {groups.map(group => <p key={group.id} className="flex min-w-32 justify-between gap-6"><span>{group.label}</span><span className="tabular-nums text-charcoal">{fmtPct(group.total, 0)}</span></p>)}
          </div>
        </div>
        {/* Rows */}
        <table className="mt-3 w-full border-collapse">
          <thead>
            <tr className="font-mono text-[10px] uppercase tracking-wider text-muted-light">
              <th scope="col" className="text-left font-normal pb-1.5">
                Asset
              </th>
              <th scope="col" className="text-right font-normal pb-1.5 w-16">
                Weight
              </th>
              <th scope="col" className="text-right font-normal pb-1.5 w-16 hidden sm:table-cell">
                μ<sub>BL</sub>
              </th>
              <th scope="col" className="text-right font-normal pb-1.5 w-16 hidden sm:table-cell">
                vs Π
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r) => {
              const zero = r.w < 0.001;
              const active = hover === r.asset.ticker;
              const delta = r.mu - r.prior;
              return (
                <motion.tr layout="position" transition={reduced ? { duration: 0 } : { type: 'spring', stiffness: 360, damping: 32 }}
                  key={r.asset.ticker}
                  data-unallocated={zero || undefined}
                  className={`border-t border-border/70 transition-colors ${active ? 'bg-accent/5' : ''} ${zero ? 'bg-surface-alt' : ''}`}
                  onMouseEnter={() => setHover(r.asset.ticker)}
                  onMouseLeave={() => setHover(null)}
                >
                  <td className="py-1.5 pr-2">
                    <div className="flex items-center gap-2 min-w-0">
                      <span aria-hidden="true" className="inline-block w-2.5 h-2.5 rounded-[2px] shrink-0" style={{ background: ASSET_COLORS[r.asset.ticker] }} />
                      <button type="button" aria-label={`${r.asset.name}: ${fmtPct(r.w)}`} aria-pressed={active}
                        onFocus={() => setHover(r.asset.ticker)} onBlur={() => setHover(null)}
                        onClick={() => setHover(r.asset.ticker)}
                        className="min-h-6 w-9 shrink-0 rounded text-left font-mono text-xs text-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-accent">{r.asset.ticker}</button>
                      <span className="font-sans text-xs text-muted truncate" title={r.asset.description}>
                        {r.asset.name}
                      </span>
                    </div>
                  </td>
                  <td className="py-1.5 text-right font-mono text-xs text-charcoal tabular-nums">{fmtPct(r.w)}</td>
                  <td className="py-1.5 text-right font-mono text-xs text-muted tabular-nums hidden sm:table-cell">{fmtPct(r.mu)}</td>
                  <td className="py-1.5 text-right font-mono text-xs tabular-nums hidden sm:table-cell">
                    <span className={delta > 0.0005 ? 'text-positive' : delta < -0.0005 ? 'text-negative' : 'text-muted-light'}>{fmtSignedPct(delta)}</span>
                  </td>
                </motion.tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

src/app/components/optimizer/ComparisonT:
'use client';

import React from 'react';
import { Table2 } from 'lucide-react';
import type { AllocationResult, SimulationOutput } from '@/lib/optimizer/engine';
import { STRATEGY_COLORS, fmtMoney, fmtNum, fmtPct } from './format';
import { PanelTitle } from './primitives';

type Key = 'adaptive' | 'benchmark' | 'cash';

interface Row {
  label: string;
  hint?: string;
  values: Record<Key, number>;
  format: (v: number) => string;
  /** Which direction is "better", for the subtle emphasis on the best cell. */
  better: 'high' | 'low';
}

export default function ComparisonTable({ alloc, sim }: { alloc: AllocationResult; sim: SimulationOutput }) {
  const [ad, bm, cs] = sim.strategies;
  const s = alloc.stats;

  const rows: Row[] = [
    { label: 'Expected return', hint: 'μ_BL · annual', values: { adaptive: s.adaptive.ret, benchmark: s.benchmark.ret, cash: s.cash.ret }, format: (v) => fmtPct(v, 2), better: 'high' },
    { label: 'Volatility', hint: 'σ · annual', values: { adaptive: s.adaptive.vol, benchmark: s.benchmark.vol, cash: s.cash.vol }, format: (v) => fmtPct(v, 2), better: 'low' },
    { label: '95% CVaR', hint: '1-yr expected tail loss', values: { adaptive: s.adaptive.cvar, benchmark: s.benchmark.cvar, cash: s.cash.cvar }, format: (v) => fmtPct(v, 2), better: 'low' },
    { label: 'Simulated Sharpe', hint: 'from the paths', values: { adaptive: ad.simulated.sharpe, benchmark: bm.simulated.sharpe, cash: cs.simulated.sharpe }, format: (v) => fmtNum(v, 2), better: 'high' },
    { label: 'Median wealth', hint: `year ${Number(ad.times[ad.times.length - 1].toFixed(1))}`, values: { adaptive: ad.terminal.p50, benchmark: bm.terminal.p50, cash: cs.terminal.p50 }, format: fmtMoney, better: 'high' },
    { label: 'Stress wealth', hint: '5th percentile', values: { adaptive: ad.terminal.p5, benchmark: bm.terminal.p5, cash: cs.terminal.p5 }, format: fmtMoney, better: 'high' },
    { label: 'Bull wealth', hint: '95th percentile', values: { adaptive: ad.terminal.p95, benchmark: bm.terminal.p95, cash: cs.terminal.p95 }, format: fmtMoney, better: 'high' },
    { label: 'P(shortfall)', hint: 'ends below money paid in', values: { adaptive: ad.shortfallProbability, benchmark: bm.shortfallProbability, cash: cs.shortfallProbability }, format: (v) => fmtPct(v, 1), better: 'low' },
  ];

  const cols: { key: Key; label: string; color: string }[] = [
    { key: 'adaptive', label: 'Adaptive Geopolitical', color: STRATEGY_COLORS.adaptive },
    { key: 'benchmark', label: 'Static 60/40', color: STRATEGY_COLORS.benchmark },
    { key: 'cash', label: '100% T-Bills', color: STRATEGY_COLORS.cash },
  ];

  return (
    <div>
      <PanelTitle icon={Table2} title="Strategy Comparison" hint={`paid in ${fmtMoney(sim.totalContributed)}`} />
      {/* Focusable: a scroll container that a keyboard cannot enter strands
          the columns that overflow. */}
      <div className="p-4 pt-2 overflow-x-auto" data-scroll-region tabIndex={0} role="group" aria-label="Strategy comparison">
        <table className="w-full min-w-[420px] border-collapse">
          <thead>
            <tr>
              <th scope="col" className="text-left font-mono text-[10px] uppercase tracking-wider text-muted-light font-normal py-2 pr-2">
                Metric
              </th>
              {cols.map((c) => (
                <th key={c.key} scope="col" className="text-right font-mono text-[10px] uppercase tracking-wider text-muted font-normal py-2 pl-2">
                  <span className="inline-flex items-center gap-1.5">
                    <span aria-hidden="true" className="inline-block w-2.5 h-2.5 rounded-[2px]" style={{ background: c.color }} />
                    {c.label}
                  </span>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((r) => {
              const vals = cols.map((c) => r.values[c.key]);
              const bestVal = r.better === 'high' ? Math.max(...vals) : Math.min(...vals);
              return (
                <tr key={r.label} className="border-t border-border/70">
                  <th scope="row" className="text-left py-1.5 pr-2 font-normal">
                    <span className="font-sans text-xs text-charcoal">{r.label}</span>
                    {r.hint ? <span className="block font-mono text-[10px] text-muted-light">{r.hint}</span> : null}
                  </th>
                  {cols.map((c) => {
                    const v = r.values[c.key];
                    const best = Math.abs(v - bestVal) < 1e-12;
                    return (
                      <td key={c.key} className={`py-1.5 pl-2 text-right font-mono text-xs tabular-nums ${best ? 'text-charcoal' : 'text-muted'}`}>
                        {r.format(v)}
                      </td>
                    );
                  })}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

src/app/components/optimizer/ControlPane:
'use client';

import React, { useId } from 'react';
import { Earth, Flame, Swords, TrendingDown, SlidersHorizontal, Shield, Scale, Zap, ShieldCheck } from 'lucide-react';
import type { OptimizerInputs, RiskProfile } from '@/lib/optimizer/engine';
import { PROFILES } from '@/lib/optimizer/engine';
import { REGIMES, REGIME_BY_ID, type AppliedView, type RegimeId } from '@/lib/optimizer/blackLitterman';
import { FieldLabel, Panel, PanelTitle, SegmentedChoice, Slider } from './primitives';
import { fmtMoneyFull, fmtPct } from './format';

const REGIME_ICONS: Record<RegimeId, typeof Earth> = {
  cooperative: Earth,
  inflation: Flame,
  conflict: Swords,
  stagnation: TrendingDown,
};

const PROFILE_ICONS: Record<RiskProfile, typeof Shield> = {
  conservative: Shield,
  moderate: Scale,
  aggressive: Zap,
  hedged: ShieldCheck,
};

const thetaCaption = (theta: number) =>
  theta < 0.2
    ? 'Cyclical data dominates; regime views barely move the prior.'
    : theta < 0.5
      ? 'Structural trends tilt the posterior modestly.'
      : theta < 0.8
        ? 'Structural trends carry most of the weight.'
        : 'Regime views applied at near-full conviction.';

function MoneyInput({
  id,
  value,
  min,
  step,
  onCommit,
}: {
  id: string;
  value: number;
  min: number;
  step: number;
  onCommit: (v: number) => void;
}) {
  const [text, setText] = React.useState(String(value));
  const [focused, setFocused] = React.useState(false);
  React.useEffect(() => {
    if (!focused) setText(String(value));
  }, [value, focused]);
  const commit = (raw: string) => {
    const n = Number(raw.replace(/[^0-9.]/g, ''));
    if (Number.isFinite(n)) onCommit(Math.max(min, Math.round(n)));
  };
  return (
    <div className="relative">
      <span className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 font-mono text-xs text-muted-light">$</span>
      <input
        id={id}
        type="text"
        inputMode="decimal"
        value={focused ? text : fmtMoneyFull(value).replace('$', '')}
        min={min}
        step={step}
        onFocus={() => {
          setFocused(true);
          setText(String(value));
        }}
        onBlur={(e) => {
          setFocused(false);
          commit(e.target.value);
        }}
        onChange={(e) => {
          setText(e.target.value);
          commit(e.target.value);
        }}
        className="w-full bg-surface-alt/70 border border-border rounded-editorial pl-6 pr-2.5 py-1.5 font-mono text-sm text-charcoal tabular-nums focus:outline-none focus:border-accent/60 focus-visible:ring-2 focus-visible:ring-accent/40"
      />
    </div>
  );
}

export default function ControlPanel({
  inputs,
  onChange,
  views,
}: {
  inputs: OptimizerInputs;
  onChange: (patch: Partial<OptimizerInputs>) => void;
  views: AppliedView[];
}) {
  const uid = useId();
  const regime = REGIME_BY_ID[inputs.regime];

  return (
    <Panel className="h-full">
      <PanelTitle icon={SlidersHorizontal} title="Control & Macro Inputs" />
      <div className="p-4 space-y-5">
        {/* Capital */}
        <div className="grid grid-cols-2 gap-3">
          <div>
            <FieldLabel htmlFor={`${uid}-cap`}>Initial capital</FieldLabel>
            <MoneyInput id={`${uid}-cap`} value={inputs.initialCapital} min={1000} step={1000} onCommit={(v) => onChange({ initialCapital: v })} />
          </div>
          <div>
            <FieldLabel htmlFor={`${uid}-contrib`}>Monthly contribution</FieldLabel>
            <MoneyInput id={`${uid}-contrib`} value={inputs.monthlyContribution} min={0} step={100} onCommit={(v) => onChange({ monthlyContribution: v })} />
          </div>
        </div>

        {/* Horizon */}
        <div>
          <FieldLabel htmlFor={`${uid}-horizon`} value={`${inputs.horizonYears} yr`}>
            Investment horizon
          </FieldLabel>
          <Slider
            id={`${uid}-horizon`}
            min={1}
            max={30}
            step={1}
            value={inputs.horizonYears}
            aria-valuetext={`${inputs.horizonYears} years`}
            onChange={(e) => onChange({ horizonYears: Number(e.target.value) })}
          />
          <div className="flex justify-between font-mono text-[10px] text-muted-light mt-1">
            <span>1</span>
            <span>15</span>
            <span>30</span>
          </div>
        </div>

        {/* Risk profile */}
        <div>
          <FieldLabel>Risk tolerance</FieldLabel>
          <SegmentedChoice
            label="Risk tolerance"
            value={inputs.profile}
            onChange={(profile) => onChange({ profile })}
            options={PROFILES.map((p) => ({ id: p.id, label: p.name, icon: PROFILE_ICONS[p.id], hint: p.summary }))}
          />
        </div>

        {/* Regime */}
        <div>
          <FieldLabel>Geopolitical shock / regime</FieldLabel>
          <SegmentedChoice
            label="Macro regime"
            value={inputs.regime}
            onChange={(r) => onChange({ regime: r })}
            options={REGIMES.map((r) => ({ id: r.id, label: r.name, icon: REGIME_ICONS[r.id], hint: r.summary }))}
            columns={1}
          />
          <p className="mt-2 font-sans text-xs leading-relaxed text-muted">{regime.summary}</p>
        </div>

        {/* Theta */}
        <div>
          <FieldLabel htmlFor={`${uid}-theta`} value={`θ = ${inputs.theta.toFixed(2)}`}>
            Geopolitical inertia
          </FieldLabel>
          <Slider
            id={`${uid}-theta`}
            min={0}
            max={1}
            step={0.01}
            value={inputs.theta}
            aria-valuetext={`theta ${inputs.theta.toFixed(2)}`}
            onChange={(e) => onChange({ theta: Number(e.target.value) })}
          />
          <div className="flex justify-between font-mono text-[10px] text-muted-light mt-1">
            <span>Cyclical</span>
            <span>Structural</span>
          </div>
          <p className="mt-1.5 font-sans text-xs text-muted">{thetaCaption(inputs.theta)}</p>
        </div>

        {/* Sentiment */}
        <div>
          <FieldLabel htmlFor={`${uid}-sent`} value={`${inputs.sentiment > 0 ? '+' : ''}${Math.round(inputs.sentiment * 100)}`}>
            Equity sentiment
          </FieldLabel>
          <Slider
            id={`${uid}-sent`}
            min={-1}
            max={1}
            step={0.05}
            value={inputs.sentiment}
            aria-valuetext={`sentiment ${Math.round(inputs.sentiment * 100)}`}
            onChange={(e) => onChange({ sentiment: Number(e.target.value) })}
          />
          <div className="flex justify-between font-mono text-[10px] text-muted-light mt-1">
            <span>Bearish</span>
            <span>Neutral</span>
            <span>Bullish</span>
          </div>
        </div>

        {/* Active views */}
        <div>
          <FieldLabel value={`${views.length} views`}>Active Black-Litterman views</FieldLabel>
          <ul className="space-y-1">
            {views.map((v) => (
              <li key={v.label} className="flex items-baseline justify-between gap-2 font-mono text-[11px] leading-snug">
                <span className={`truncate ${v.isSentiment ? 'text-accent' : 'text-charcoal'}`} title={v.label}>
                  {v.label}
                </span>
                <span className="shrink-0 tabular-nums text-muted">
                  {fmtPct(v.q, 1)} · c {Math.round(v.confidence * 100)}%
                </span>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </Panel>
  );
}

