/*
 * Working Volumes — authored stylesheet.
 *
 * Ported from the registered ThreeUI source for `CompleteShelfLandingPage`
 * (public/landing-pages/complete-shelf-v2.html, SHA-256 606f200fed86…,
 * verified on download). Declarations are the authored ones, unchanged.
 *
 * Only the selectors are rewritten, and only because the source is a
 * standalone document while this is one route inside a Next app:
 *
 *   :root            ->  .shelf-root
 *   html, body       ->  html[data-shelf], html[data-shelf] body
 *   *                ->  .shelf-root *
 *   everything else  ->  .shelf-root <selector>
 *
 * `data-shelf` is set on <html> by <Shelf /> while it is mounted and removed on
 * unmount, so the document-level rules — including `overflow: hidden` — apply
 * on the shelf route and nowhere else.
 *
 * This file is generated. Do not hand-edit it.
 */

html[data-shelf], .shelf-root {
      color-scheme: dark;
      --paper: #171a24;
      --paper-deep: #10131b;
      --paper-pale: #f1eadf;
      --ink: #f4eee6;
      --ink-soft: #b9b4ae;
      --walnut: #3a2118;
      --walnut-deep: #1c0e0a;
      --rule: rgba(244, 238, 230, 0.24);
      --accent: #c87046;
      --serif: "Iowan Old Style", "Baskerville", "Times New Roman", serif;
      --mono: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
      --ease-out: cubic-bezier(0.2, 0.72, 0.24, 1);
    }

.shelf-root * {
      box-sizing: border-box;
    }

html[data-shelf], html[data-shelf] body,
html[data-shelf], html[data-shelf] body {
      width: 100%;
      min-height: 100%;
      margin: 0;
      overflow: hidden;
      background: var(--paper);
      color: var(--ink);
    }

html[data-shelf], html[data-shelf] body {
      font-family: var(--serif);
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
    }

.shelf-root button {
      color: inherit;
      font: inherit;
    }

.shelf-root button:focus-visible {
      outline: 1px solid var(--ink);
      outline-offset: 4px;
    }

.shelf-root [hidden] {
      display: none !important;
    }

.shelf-root .experience {
      position: fixed;
      inset: 0;
      isolation: isolate;
      overflow: hidden;
      background: var(--paper);
      transition: background-color 720ms var(--ease-out), color 520ms var(--ease-out);
    }

.shelf-root .frame {
      position: absolute;
      inset: 18px;
      z-index: 8;
      border: 1px solid var(--rule);
      pointer-events: none;
    }

.shelf-root .frame::before,
.shelf-root .frame::after {
      position: absolute;
      width: 18px;
      height: 18px;
      border-color: rgba(42, 34, 27, 0.48);
      content: "";
    }

.shelf-root .frame::before {
      top: -1px;
      left: -1px;
      border-top: 1px solid;
      border-left: 1px solid;
    }

.shelf-root .frame::after {
      right: -1px;
      bottom: -1px;
      border-right: 1px solid;
      border-bottom: 1px solid;
    }

.shelf-root .masthead {
      position: absolute;
      top: 40px;
      right: 42px;
      left: 42px;
      z-index: 7;
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 32px;
      transition: opacity 500ms var(--ease-out), transform 700ms var(--ease-out);
      pointer-events: none;
    }

.shelf-root .identity {
      display: grid;
      grid-template-columns: auto auto;
      align-items: baseline;
      gap: 12px;
    }

.shelf-root .identity__name {
      margin: 0;
      font-size: clamp(1.02rem, 1.55vw, 1.36rem);
      font-weight: 500;
      letter-spacing: -0.025em;
    }

.shelf-root .identity__edition,
.shelf-root .issue,
.shelf-root .eyebrow,
.shelf-root .microcopy,
.shelf-root .counter,
.shelf-root .meta-list dt,
.shelf-root .folio,
.shelf-root .fallback__kicker {
      font-family: var(--mono);
      font-size: 0.66rem;
      font-weight: 500;
      letter-spacing: 0.15em;
      line-height: 1.45;
      text-transform: uppercase;
    }

.shelf-root .identity__edition {
      color: var(--ink-soft);
    }

.shelf-root .issue {
      max-width: 260px;
      margin: 1px 0 0;
      color: var(--ink-soft);
      text-align: right;
    }

.shelf-root .hero-word {
      position: absolute;
      top: 12.5%;
      left: 50%;
      z-index: 1;
      margin: 0;
      color: rgba(68, 50, 34, 0.075);
      font-size: clamp(7rem, 20vw, 20rem);
      font-weight: 400;
      letter-spacing: -0.085em;
      line-height: 0.75;
      text-transform: uppercase;
      transform: translateX(-51%);
      white-space: nowrap;
      pointer-events: none;
      transition: opacity 600ms var(--ease-out), transform 900ms var(--ease-out);
    }

.shelf-root .scene-shell {
      position: absolute;
      inset: 0;
      z-index: 3;
    }

.shelf-root #scene {
      display: block;
      width: 100%;
      height: 100%;
      cursor: default;
      opacity: 0;
      touch-action: none;
      transition: opacity 900ms var(--ease-out);
    }

.shelf-root .webgl-ready #scene {
      opacity: 1;
    }

.shelf-root .pointer-label {
      position: fixed;
      z-index: 12;
      display: grid;
      min-width: 128px;
      padding: 9px 12px 8px;
      border: 1px solid rgba(39, 30, 22, 0.24);
      background: rgba(244, 236, 219, 0.92);
      box-shadow: 0 8px 24px rgba(59, 38, 22, 0.08);
      font-family: var(--mono);
      font-size: 0.61rem;
      letter-spacing: 0.12em;
      line-height: 1.45;
      text-transform: uppercase;
      transform: translate(16px, 18px);
      transition: opacity 120ms ease;
      pointer-events: none;
      backdrop-filter: blur(8px);
    }

.shelf-root .pointer-label[aria-hidden="true"] {
      opacity: 0;
    }

.shelf-root .browse-ui {
      position: absolute;
      right: 42px;
      bottom: 38px;
      left: 42px;
      z-index: 7;
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
      align-items: end;
      gap: 28px;
      transition: opacity 400ms var(--ease-out), transform 650ms var(--ease-out);
    }

.shelf-root .selection {
      display: grid;
      grid-template-columns: auto minmax(0, 1fr);
      align-items: end;
      gap: 16px;
      min-width: 0;
    }

.shelf-root .counter {
      padding-bottom: 5px;
      color: var(--ink-soft);
      font-variant-numeric: tabular-nums;
      white-space: nowrap;
    }

.shelf-root .selection__copy {
      min-width: 0;
    }

.shelf-root .selection__title {
      margin: 0;
      overflow: hidden;
      font-size: clamp(1.7rem, 3vw, 3.1rem);
      font-weight: 400;
      letter-spacing: -0.055em;
      line-height: 0.98;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

.shelf-root .selection__note {
      max-width: 480px;
      margin: 7px 0 0;
      color: var(--ink-soft);
      font-size: 0.86rem;
      line-height: 1.45;
    }

.shelf-root .browse-actions {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
    }

.shelf-root .round-button,
.shelf-root .text-button,
.shelf-root .close-button {
      border: 1px solid rgba(43, 34, 27, 0.28);
      background: rgba(244, 236, 219, 0.72);
      cursor: pointer;
      transition:
        color 180ms ease,
        border-color 180ms ease,
        background 180ms ease,
        transform 180ms var(--ease-out);
      backdrop-filter: blur(8px);
    }

.shelf-root .round-button {
      display: grid;
      width: 42px;
      height: 42px;
      padding: 0;
      border-radius: 50%;
      place-items: center;
    }

.shelf-root .round-button:hover,
.shelf-root .text-button:hover,
.shelf-root .close-button:hover {
      border-color: var(--ink);
      background: var(--paper-pale);
      transform: translateY(-2px);
    }

.shelf-root .round-button svg,
.shelf-root .close-button svg {
      width: 15px;
      height: 15px;
      fill: none;
      stroke: currentColor;
      stroke-linecap: round;
      stroke-linejoin: round;
      stroke-width: 1.25;
    }

.shelf-root .text-button {
      min-height: 42px;
      padding: 0 19px;
      border-radius: 999px;
      font-family: var(--mono);
      font-size: 0.65rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

.shelf-root .index-nav {
      display: grid;
      justify-items: end;
      gap: 12px;
    }

.shelf-root .markers {
      display: flex;
      align-items: center;
      justify-content: flex-end;
      gap: 9px;
    }

.shelf-root .marker {
      position: relative;
      width: 24px;
      height: 24px;
      padding: 0;
      border: 0;
      background: transparent;
      cursor: pointer;
    }

.shelf-root .marker::before {
      position: absolute;
      top: 50%;
      left: 50%;
      width: 4px;
      height: 4px;
      border-radius: 50%;
      background: rgba(48, 39, 31, 0.34);
      content: "";
      transform: translate(-50%, -50%);
      transition: width 260ms var(--ease-out), background 220ms ease;
    }

.shelf-root .marker:hover::before {
      background: var(--ink);
    }

.shelf-root .marker[aria-current="true"]::before {
      width: 19px;
      border-radius: 4px;
      background: var(--accent);
    }

.shelf-root .microcopy {
      margin: 0;
      color: var(--ink-soft);
      text-align: right;
    }

.shelf-root .detail-panel {
      position: absolute;
      top: 20%;
      right: clamp(42px, 7vw, 116px);
      z-index: 9;
      width: min(38vw, 470px);
      max-height: 68vh;
      padding: clamp(24px, 3vw, 42px);
      overflow: auto;
      border: 1px solid rgba(49, 38, 28, 0.22);
      background:
        linear-gradient(90deg, rgba(84, 58, 37, 0.055), transparent 6%, transparent 94%, rgba(84, 58, 37, 0.045)),
        rgba(244, 237, 220, 0.91);
      box-shadow:
        0 28px 80px rgba(56, 36, 21, 0.12),
        inset 0 0 36px rgba(113, 79, 46, 0.055);
      opacity: 0;
      transform: translateY(28px);
      transition: opacity 620ms var(--ease-out), transform 620ms var(--ease-out);
      pointer-events: none;
      backdrop-filter: blur(14px);
    }

.shelf-root .detail-panel::before {
      position: absolute;
      top: 0;
      bottom: 0;
      left: 50%;
      width: 1px;
      background: linear-gradient(180deg, transparent, rgba(74, 52, 35, 0.08), transparent);
      content: "";
      pointer-events: none;
    }

.shelf-root .mode-detail .detail-panel {
      opacity: 1;
      transform: translateY(0);
      transition-delay: 0ms, 300ms, 300ms;
      pointer-events: auto;
    }

.shelf-root .mode-detail.is-opening .detail-panel {
      pointer-events: none;
    }

.shelf-root .mode-detail .browse-ui {
      opacity: 0;
      transform: translateY(28px);
      pointer-events: none;
    }

.shelf-root .mode-detail .hero-word {
      opacity: 0.22;
      transform: translateX(-51%) scale(0.96);
    }

.shelf-root .mode-detail .masthead {
      opacity: 0.34;
      transform: translateY(-8px);
    }

.shelf-root .close-button {
      position: absolute;
      top: 18px;
      right: 18px;
      display: grid;
      width: 38px;
      height: 38px;
      padding: 0;
      border-radius: 50%;
      place-items: center;
    }

.shelf-root .eyebrow {
      margin: 0 46px 18px 0;
      color: var(--ink);
    }

.shelf-root .detail-title {
      max-width: 90%;
      margin: 0;
      font-size: clamp(2.4rem, 5vw, 5.2rem);
      font-weight: 500;
      letter-spacing: -0.05em;
      line-height: 0.92;
    }

.shelf-root .detail-deck {
      margin: 22px 0 0;
      font-size: clamp(1rem, 1.35vw, 1.22rem);
      line-height: 1.55;
    }

.shelf-root .detail-deck::first-letter {
      float: left;
      margin: 5px 7px 0 0;
      color: var(--accent);
      font-size: 3.25em;
      line-height: 0.72;
    }

.shelf-root .meta-list {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 18px 24px;
      margin: 30px 0 0;
      padding: 22px 0 0;
      border-top: 1px solid var(--rule);
    }

.shelf-root .meta-list div {
      min-width: 0;
    }

.shelf-root .meta-list dt {
      margin: 0 0 6px;
      color: var(--ink-soft);
    }

.shelf-root .meta-list dd {
      margin: 0;
      font-size: 0.86rem;
      line-height: 1.45;
    }

.shelf-root .detail-controls {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 14px;
      margin-top: 28px;
      padding-top: 18px;
      border-top: 1px solid var(--rule);
    }

.shelf-root .detail-controls .microcopy {
      text-align: left;
