  .sketchbook-root .sb-head { padding: 0 0 20px !important; }
  .sketchbook-root .sb-running,.sketchbook-root .sb-smallprint { color: #222 !important; }
  .sketchbook-root .sb-back { display: none; }
  .reader-section { break-inside: auto; }
  .reader-heading { break-after: avoid; }
  .reader-evidence article,figure { break-inside: avoid; }
  .reader-instrument-button { display: none; }
}

