.sketchbook-root .tool-sep {
  width:1px;height:17px;background:var(--hairline);margin:0 2px
}

.sketchbook-root .zoom-read {
  font-size:11px;letter-spacing:.1em;color:var(--ink-faint);
  min-width:40px;text-align:center;font-variant-numeric:tabular-nums;
}

@media (pointer:coarse) {
  .sketchbook-root .loupe {
    display:none
  }
}

.sketchbook-root .sb-zone {
  position:absolute;top:0;bottom:0;border:0;background:transparent;cursor:grab;z-index:60;-webkit-tap-highlight-color:transparent
}

.sketchbook-root .sb-zone:active {
  cursor:grabbing
