.sketchbook-root .sb-prev {
  left:0;width:50%
}

.sketchbook-root .sb-next {
  right:0;width:50%
}

.sketchbook-root .sb-captions {
  display:grid;justify-items:center
}

.sketchbook-root .sb-captions>* {
  grid-area:1/1;margin:0
}

.sketchbook-root .sb-caption {
  font-size:13px;letter-spacing:var(--track-caps);text-transform:uppercase;color:var(--ink-soft);
  animation:sb-cap-in .5s ease both
}

.sketchbook-root .sb-caption.live {
  animation:none
}

@keyframes sb-cap-in {0%{opacity:0}}

@keyframes sb-cap-out {to{opacity:0}}

.sketchbook-root .sb-hint {
  margin:0;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-faint);
  transition:opacity .4s ease;
}

.sketchbook-root .sb-hint.gone {
  opacity:0
}

.sketchbook-root .sb-wrap.intro .sb-full img,
.sketchbook-root .sb-wrap.intro .sb-half-img {
  filter:url(#sb-mblur-1)
}

.sketchbook-root .sb-wrap.intro.b2 .sb-full img,
.sketchbook-root .sb-wrap.intro.b2 .sb-half-img {
  filter:url(#sb-mblur-2)
}

.sketchbook-root .sb-wrap.intro .sb-caption {
  animation:none
}

.sketchbook-root .sb-wrap.intro .sb-caption.cap-out {
  display:none
}

@media (max-width:640px) {
  .sketchbook-root .hero-kicker {
    font-size:10.5px;letter-spacing:.16em
  }

  .sketchbook-root .sb-wrap {
    width:100vw;margin-inline:calc(50% - 50vw)
  }

  .sketchbook-root .sb-arrow {
    position:absolute;top:50%;transform:translateY(-50%);z-index:70;padding:12px 6px
  }

  .sketchbook-root .sb-arrow.left {
    left:2px
  }

  .sketchbook-root .sb-arrow.right {
    right:2px
  }

  .sketchbook-root .sb-3d {
    max-width:none
  }

  .sketchbook-root .sb-hint {
    font-size:9.5px;letter-spacing:.1em;padding:0 16px;text-align:center
  }
}

/* ---------------- painted rules + sections ---------------- */

.sketchbook-root .rule {
  display:block;width:min(1080px,86vw);margin:clamp(30px,6vh,64px) auto;
  height:clamp(26px,4vw,46px);
  background:url(/sketchbook/divider.png) center / 100% auto no-repeat;
  opacity:.5;
}

.sketchbook-root .rule.short {
  width:min(420px,52vw);opacity:.4
}

.sketchbook-root .section-label {
  font-size:11px;letter-spacing:var(--track-caps);text-transform:uppercase;
  color:var(--ink-faint);margin:0 0 18px;
}

.sketchbook-root .about {
  position:relative;max-width:1080px;margin:0 auto;
  padding:0 clamp(20px,5vw,48px);
  display:grid;grid-template-columns:minmax(0,1fr) auto;gap:clamp(24px,5vw,60px);align-items:start;
}

.sketchbook-root .bio {
  font-size:clamp(17px,1.7vw,20px);line-height:1.74;letter-spacing:.005em;margin:0;font-weight:300;max-width:56ch
