  text-underline-offset:4px;transition:text-decoration-color .2s
}

.sketchbook-root .bio-link:hover {
  text-decoration-color:var(--ink)
}

@media (max-width:760px) {
  .sketchbook-root .about {
    grid-template-columns:1fr
  }
