'use client';

import { MotionConfig } from 'motion/react';
import type { ReactNode } from 'react';

export default function MotionProvider({ children }: { children: ReactNode }) {
  return <MotionConfig reducedMotion="user" transition={{ type: 'spring', stiffness: 400, damping: 32 }}>{children}</MotionConfig>;
}

src/app/globals.css:
@tailwind base;
@tailwind components;
@tailwind utilities;

.no-script-nav { position: relative; z-index: 30; padding: 84px 20px 12px; display: flex; flex-wrap: wrap; gap: 20px; }
.no-script-nav a { min-height: 44px; padding-block: 10px; text-decoration: underline; }

/*
 * TYPE, AND WHY THERE IS ONLY ONE SET OF IT.
 *
 * The site used to render in three different type systems depending on which
 * route you were on. The shelf set the whole document in its own serif, so even
 * the navigation changed face when you left the home page; the volumes used
 * Instrument Serif and Newsreader; and the colophon used a third stack whose
 * first entry, "Iowan Old Style", exists only on macOS — so it silently fell
 * back to a fourth face for everyone else. Changing page changed the typography,
 * which is what this fixes.
 *
 * There are three roles now and one face for each, everywhere:
 *
 *   --font-display   Instrument Serif   every title and heading
 *   --font-text      Newsreader         every run of prose
 *   --font-ui        Inter              navigation, controls, small-caps labels
 *
 * The two serifs are the faces the sketchbook design names, self-hosted from
 * `public/sketchbook/` and verified byte-for-byte against their published
 * hashes. Declaring them here rather than in `sketchbook.css` is what makes them
 * available on every route instead of only inside a book — the generator drops
 * its own copies for that reason.
 *
 * Inter and JetBrains Mono still come through next/font in the layout, which
 * self-hosts them and inlines their @font-face rules. Cormorant Garamond was
 * dropped: nothing asks for it any more.
 */
@font-face {
  font-family: 'Instrument Serif';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(/sketchbook/instrument-serif.woff2) format('woff2');
}

@font-face {
  font-family: 'Instrument Serif';
  font-style: italic;
  font-weight: 400;
  font-display: swap;
  src: url(/sketchbook/instrument-serif-italic.woff2) format('woff2');
}

@font-face {
  font-family: 'Newsreader';
  font-style: normal;
  font-weight: 200 600;
  font-display: swap;
  src: url(/sketchbook/newsreader.woff2) format('woff2');
}

/*
 * THEME TOKENS
 *
 * Every colour in the site resolves through these channel triplets: the
 * Tailwind token names (cream / charcoal / surface / accent ...) are bound to
 * `rgb(var(--c-*) / <alpha-value>)` in tailwind.config.js, so no component has
 * to know a colour, only a role. Values are space-separated channels, not hex,
 * because that is the only form Tailwind's <alpha-value> placeholder composes
 * with.
 *
 * ONE GROUND, AND IT IS THE SHELF'S.
 *
 * There used to be two themes, a warm paper one and a dark one, with a toggle
 * and a pre-paint script to resolve them. That made sense when the site was a
 * conventional set of pages. It stopped making sense when the shelf became the
 * site: the ThreeUI scene is lit for #171A24 and cannot be re-lit per theme,
 * so the paper theme put a cream page around a dark canvas and every route had
 * to negotiate the seam.
 *
 * So the ground below is the shelf's own `--paper`, and every surface above it
 * is a translucent step off it rather than a second colour. Chrome — the nav,
 * the panels, the form fields — is transparent over the scene instead of a bar
 * laid across it.
 *
 * Contrast is not assumed. Every pair a visitor reads is asserted by
 * scripts/check-contrast.mjs against WCAG 2.2 AA, and scripts/a11y.mjs scans
 * the rendered result.
 */
:root {
  /*
   * Ground + surfaces: a warm espresso, not a blue-black.
   *
   * This used to be the shelf's `#171A24`, which is ultramarine dark — a cool
   * ground that made the whole site read cold and gave the warm accent nothing
   * to sit on. The room is warm now and the shelf's own scene was warmed with
   * it (see the palettes in `volumes.ts`), so the page and the canvas still
   * meet without a seam.
   */
  --c-ground: 26 21 17;
  --c-panel: 34 27 22;
  --c-panel-alt: 30 24 20;
  --c-panel-raised: 43 35 28;
  --c-hairline: 58 47 38;
  --c-hairline-strong: 81 66 53;
  /* Boundary for interactive controls -- input, select, textarea edges. WCAG
     1.4.11 wants 3:1 for the edge of a control a person has to find, which the
     decorative hairlines above do not and need not meet. Verified by
     scripts/check-contrast.mjs. */
  --c-hairline-control: 138 116 97;

  /* Type ramp: warm bone down to a decorative dim. */
  --c-text: 242 234 224;
  --c-text-2: 228 218 205;
  --c-text-3: 205 193 178;
  --c-muted: 182 168 151;
  --c-muted-light: 150 137 122;

  /*
   * The single accent, deliberately quiet.
   *
   * It was #D68558 — a saturated salmon that filled every call to action with a
   * bright pill and made the site look generated rather than designed. This is
   * an old brass instead: warm, low-chroma, and used as ink and as a hairline
   * rather than as a fill. Nothing on the site is a solid block of it any more.
   */
  --c-brass: 194 156 110;
  --c-brass-hi: 222 196 160;
  --c-brass-lo: 148 116 78;
  --c-brass-hover: 214 182 144;
  --c-copper: 180 137 100;
  --c-copper-hi: 205 168 134;
  --c-copper-lo: 142 104 72;

  --c-positive: 146 172 128;
  --c-negative: 206 140 124;
  /* Caution is its own burnt tone rather than an alias of brass, so a
     "synthetic sample" badge cannot be mistaken for an ordinary accent. */
  --c-caution: 214 154 98;

  --c-scroll-thumb: 58 47 38;
  --c-scroll-thumb-hover: 81 66 53;
  /* Canvas scan light, and a multiplier for canvas line alphas. */
  --c-scan: 242 234 224;
  --canvas-alpha: 1;

  /* Elevation on a dark ground is shadow, not cast. */
  --shadow-card: 0 2px 8px rgba(0, 0, 0, 0.3);
  --shadow-card-hover: 0 16px 40px rgba(0, 0, 0, 0.36);
  --shadow-hairline: inset 0 1px 0 0 rgba(255, 255, 255, 0.04);
  --shadow-glow: 0 0 12px rgb(var(--c-brass) / 0.4);
  --shadow-glow-blue: 0 0 16px rgb(var(--c-copper) / 0.28);

  /* Studio photography sits on this ground only after being knocked back. */
  --plate-filter: brightness(0.78) contrast(1.06) saturate(0.84);
  --portrait-filter: saturate(0.9) brightness(0.97);
  /*
   * The brand mark is used as drawn.
   *
   * It was inverted, which turned a dark monogram on white into a white smear
   * on the dark bar. The artwork has its own opaque white ground; letting it
   * keep it is what "natural" means here, and it reads as a printed card on the
   * rail rather than a filtered asset.
   */
  --brand-filter: none;

  /* The three type roles. Every surface on the site resolves to one of them. */
  --font-display: 'Instrument Serif', 'Times New Roman', Georgia, serif;
  --font-text: 'Newsreader', Georgia, 'Times New Roman', serif;
  --font-ui: var(--font-sans), ui-sans-serif, system-ui, sans-serif;

  /* House easing: fast out of the gate, long soft landing. */
  --ease-luxe: cubic-bezier(0.22, 1, 0.36, 1);

  /*
   * READING SCALE
   *
   * Body copy is 18px from the medium breakpoint up and 17px below it, which is
   * comfortably inside the 16-18px target without forcing a second reflow on
   * small screens. `--measure` is the long-form column: 68ch lands at roughly
   * 65 characters for this face, inside the 60-70 range.
   */
  --text-body: 1.0625rem;
  --leading-body: 1.7;
  --measure: 68ch;
  --measure-narrow: 56ch;

  color-scheme: dark;
}

@media (min-width: 768px) {
  :root {
    --text-body: 1.125rem;
  }
}

@layer base {
  html {
    scroll-behavior: smooth;
    /* Fixed navbar height, so #anchor jumps do not land under the bar. */
    scroll-padding-top: 6rem;
  }

  body {
    background-color: rgb(var(--c-ground));
    color: rgb(var(--c-text));
    font-family: var(--font-sans), ui-sans-serif, system-ui, sans-serif;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  html,
  body {
    overflow-x: hidden;
  }

  /* Display face supports regular weight. Interface headings opt into Inter. */
  h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-display);
    font-weight: 400;
    letter-spacing: -0.03em;
    text-wrap: balance;
    text-rendering: optimizeLegibility;
  }

  ::selection {
    background: rgb(var(--c-copper) / 0.28);
    color: rgb(var(--c-text));
  }

  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }
  ::-webkit-scrollbar-track {
    background: rgb(var(--c-ground));
  }
  ::-webkit-scrollbar-thumb {
    background: rgb(var(--c-scroll-thumb));
    border: 2px solid rgb(var(--c-ground));
    border-radius: 999px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: rgb(var(--c-scroll-thumb-hover));
  }

  :focus-visible {
    outline: 2px solid rgb(var(--c-copper));
    outline-offset: 2px;
    border-radius: 2px;
  }

  @media (max-width: 768px) {
    * {
      -webkit-tap-highlight-color: transparent;
    }
    button, a {
      touch-action: manipulation;
    }
    .overflow-x-auto {
      -webkit-overflow-scrolling: touch;
    }
  }
}

@layer components {
  /*
   * Gradient border shell -- ThreeUI's signature control treatment. A 1px
   * gradient wrapper holds an inset panel, so the edge catches light at the
   * top-left and dissolves toward the bottom-right.
   */
  .shell {
    @apply relative rounded-full p-px;
    background: linear-gradient(135deg, rgb(var(--c-brass) / 0.34), rgb(var(--c-brass) / 0.02) 60%, transparent);
  }
  .shell-square {
    @apply relative rounded-editorial p-px;
    background: linear-gradient(135deg, rgb(var(--c-brass) / 0.22), rgb(var(--c-brass) / 0.02) 60%, transparent);
  }

  /* Frosted panel that lets the constellation field read through it. */
  .panel {
    @apply border border-border bg-surface/70 backdrop-blur-md shadow-card;
  }
  .panel-solid {
    @apply border border-border bg-surface shadow-card;
  }

  /* Retained for backwards compatibility with existing markup. */
  .editorial-card {
    @apply border border-border bg-surface/70 backdrop-blur-md rounded-editorial transition-all duration-500;
  }
  .editorial-card:hover {
    @apply border-border-dark shadow-card-hover -translate-y-1;
  }

  .shell-ring-primary {
    background: linear-gradient(135deg, rgb(var(--c-brass) / 0.55), rgb(var(--c-brass) / 0.05) 60%, transparent);
  }
  .shell-ring-secondary {
    background: linear-gradient(135deg, rgb(var(--c-brass) / 0.22), rgb(var(--c-brass) / 0.02) 60%, transparent);
  }

  .micro-label {
    @apply font-mono text-[0.6875rem] uppercase tracking-[0.18em] text-muted;
  }
}

@layer utilities {
  .grid-pattern {
    background-image:
      linear-gradient(rgb(var(--c-copper) / 0.06) 1px, transparent 1px),
      linear-gradient(90deg, rgb(var(--c-copper) / 0.06) 1px, transparent 1px);
    background-size: 64px 64px;
  }

  .cyber-grid {
    background-image:
      linear-gradient(rgb(var(--c-text) / 0.05) 1px, transparent 1px),
      linear-gradient(90deg, rgb(var(--c-text) / 0.05) 1px, transparent 1px);
    background-size: 40px 40px;
  }

  /* Vignette that seats content on top of the canvas field. */
  .field-vignette {
    background: linear-gradient(to bottom, transparent 0%, rgb(var(--c-ground) / 0.25) 60%, rgb(var(--c-ground) / 0.75) 100%);
  }

  .no-scrollbar::-webkit-scrollbar {
    display: none;
  }
  .no-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }

  .link-underline {
    position: relative;
  }
  .link-underline::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 0;
    height: 1px;
    background-color: rgb(var(--c-brass));
    transition: width 0.45s var(--ease-luxe);
  }
  .link-underline:hover::after {
    width: 100%;
  }

  .data-text {
    font-family: var(--font-mono), ui-monospace, monospace;
    font-variant-numeric: tabular-nums;
    letter-spacing: -0.02em;
  }

  .editorial-label {
    font-family: var(--font-mono), ui-monospace, monospace;
    font-size: 0.6875rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    color: rgb(var(--c-muted));
  }

  .heading-serif {
    font-weight: 200;
    letter-spacing: -0.03em;
  }

  .swiss-divider {
    width: 60px;
    height: 1px;
    background: linear-gradient(90deg, rgb(var(--c-brass)), transparent);
  }

  .bento-grid {
    display: grid;
    gap: 1.5rem;
    grid-template-columns: repeat(12, 1fr);
  }
  @media (max-width: 768px) {
    .bento-grid {
      grid-template-columns: 1fr;
      gap: 1rem;
    }
  }

  .image-frame {
    position: relative;
    overflow: hidden;
  }
  .image-frame::before {
    content: '';
    position: absolute;
    inset: 0;
    border: 1px solid rgb(var(--c-hairline));
    pointer-events: none;
    z-index: 1;
  }

  .preserve-3d {
    transform-style: preserve-3d;
  }
  .backface-hidden {
    backface-visibility: hidden;
  }

  .text-glow-gold {
    text-shadow: 0 0 18px rgb(var(--c-brass) / 0.35);
  }

  .text-gradient-silver {
    background: linear-gradient(135deg, rgb(var(--c-muted)) 0%, rgb(var(--c-text)) 50%, rgb(var(--c-muted-light)) 100%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
  }
  .text-gradient-blue {
    background: linear-gradient(135deg, rgb(var(--c-copper)) 0%, rgb(var(--c-copper-hi)) 50%, rgb(var(--c-copper-lo)) 100%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
  }
  .text-gradient-gold {
    background: linear-gradient(135deg, rgb(var(--c-brass)) 0%, rgb(var(--c-brass-hi)) 50%, rgb(var(--c-brass-lo)) 100%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
  }
}

/*
 * THE ANIMATION KIT THAT WENT WITH THE OLD HOME PAGE.
 *
 * Removed rather than kept: a scroll-reveal system (`.reveal`, `.reveal-mask`,
 * `.reveal-word`), four staggered fade-ins, a glitch, a scan line and a golden
 * pulse. Every one of them belonged to a page that scrolled through six
 * sections of prose. Nothing scrolls now except the contact page, so nothing
 * reveals on scroll, and `scripts/find-orphans.mjs` had already flagged the
 * component that drove them.
 */

/* Honour the OS-level motion preference across every decorative animation. */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}


/* ------------------------------------------------------------------------
 * SURFACE
 *
 * What is left of a much larger layer. The grain and vignette stack is a port
 * of a ThreeUI authored-scene convention (github.com/MengTo/threeui, MIT) and
 * still sits over the whole site.
 *
 * The rest of it — glass panels, Kage index rows, a marquee mask, a scroll cue,
 * a hero-exit hook, a pointer-traced ring — belonged to a home page that
 * scrolled through six sections of prose. That page is a shelf now and the
 * prose is a book, so they are gone rather than left to rot.
 * ---------------------------------------------------------------------- */

:root {
  --grain-opacity: 0.025;
  --vignette-alpha: 0.24;
}

@layer utilities {
  /*
   * Long-form reading column, for any run of copy a visitor is expected to
   * actually read rather than scan. 68ch lands at roughly 65 characters for
   * this face, inside the 60-70 target.
   */
  .measure {
    max-width: var(--measure);
  }
  .measure-narrow {
    max-width: var(--measure-narrow);
  }
  .body-text {
    font-size: var(--text-body);
    line-height: var(--leading-body);
  }

  /*
   * Fluid display sizes. The lower bound is what has to fit a 360px screen
   * without the headline dominating it; the upper bound is the editorial size.
   * clamp() means neither end needs a breakpoint, and neither end clips.
   */
  .display-1 {
    font-size: clamp(2rem, 1.35rem + 2.9vw, 3.75rem);
    line-height: 1.08;
    letter-spacing: -0.03em;
  }
  .display-2 {
    font-size: clamp(1.625rem, 1.2rem + 1.9vw, 2.75rem);
    line-height: 1.14;
    letter-spacing: -0.025em;
  }
  .display-3 {
    font-size: clamp(1.25rem, 1.05rem + 0.9vw, 1.75rem);
    line-height: 1.25;
    letter-spacing: -0.02em;
  }

  /*
   * Bounded scroll region for dense content -- tables, code, wide figures. The
   * page body must never be the thing that scrolls sideways.
   */
  .scroll-x {
    overflow-x: auto;
    max-width: 100%;
    overscroll-behavior-x: contain;
  }
}

/* Shared navigation rail and restrained interaction details. */
:root {
  --page-gutter: clamp(1.25rem, 4.5vw, 5rem);
}

.site-nav {
  background: rgb(var(--c-ground) / 0.92);
  border-bottom-color: rgb(var(--c-text) / 0.09);
}

.nav-inner {
  padding-inline: var(--page-gutter);
}

.site-nav .nav-cta {
  background: rgb(var(--c-brass) / 0.1);
  border-color: rgb(var(--c-brass) / 0.65);
}

.nav-cta svg,
.reader-cta svg {
  transition: transform 220ms var(--ease-luxe);
}

.nav-cta:hover svg,
.reader-cta:hover svg {
  transform: translateX(3px);
}

.nav-disclosure {
  border-radius: 12px;
  padding: 0.6rem;
  box-shadow: 0 24px 64px rgb(0 0 0 / 0.35);
  animation: navigation-enter 200ms var(--ease-luxe) both;
}

.nav-mobile:not([hidden]) {
  animation: navigation-enter 220ms var(--ease-luxe) both;
}

@keyframes navigation-enter {
  from { opacity: 0; translate: 0 -6px; }
  to { opacity: 1; translate: 0 0; }
}

