.chapters-portrait { position: relative; margin: 0; max-width: 230px; justify-self: end; }
.chapters-portrait img { width: 100%; aspect-ratio: 4/4.6; object-fit: cover; object-position: center 30%; filter: saturate(.7); border-radius: 3px; box-shadow: 12px 12px 0 -1px #1a1511, 12px 12px 0 0 #594936; }
.chapters-portrait figcaption { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px; margin-top: 15px; color: #b6a897; font: 400 10px/1.6 var(--font-ui); }
.portrait-edition { position: absolute; top: 22%; right: -33px; writing-mode: vertical-rl; color: #c9aa81; font: 400 10px var(--font-ui); letter-spacing: .16em; }
/* A spotlighted media reel; the narrative has its own quiet reading space. */
.career-story { --media-width: min(600px, 80vw); --card-step: calc(var(--media-width) * .84); position: relative; width: 100vw; margin-left: calc(50% - 50vw); background: #141310; border-block: 1px solid #ffffff12; scroll-margin-top: 0; }
