.career-timeline-controls { position: relative; z-index: 25; display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 30px; width: min(1120px, calc(100% - 96px)); margin: -8px auto 28px; }
.career-scroll-hint { display: flex; align-items: center; gap: 9px; color: #ada698; font: 10px/1.5 var(--font-ui); }
