.career-reel a { position: relative; display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 44px; min-width: 62px; padding-top: 8px; color: #a39b8d; font: 10px/1.5 var(--font-ui); transition: color 250ms; }
