/**
 * Black-Litterman view engine.
 *
 * A macro regime is expressed as a handful of qualitative views — absolute
 * ("gold earns 9%") or relative ("TIPS beat nominal Treasuries by 250bp") —
 * each with a confidence. Together with an optional equity-sentiment view
 * they become the pick matrix P, the view vector Q and the uncertainty
 * matrix Ω, and the posterior return μ_BL / covariance Σ_BL follow from the
 * standard closed form:
 *
 *   μ_BL = Π + τΣPᵀ (PτΣPᵀ + Ω)⁻¹ (Q − PΠ)
 *   Σ_BL = Σ + τΣ − τΣPᵀ (PτΣPᵀ + Ω)⁻¹ PτΣ
 *
 * Geopolitical inertia θ ∈ [0, 1] governs how much structural (regime) views
 * override cyclical data: it scales both the size of each view's deviation
 * from equilibrium and the confidence attached to it. θ = 0 collapses the
 * posterior onto the prior; θ = 1 applies the regime at full strength.
 */

import { INDEX, N_ASSETS, PI, SIGMA, TICKERS, type Ticker } from './universe';
import {
  dot,
  invertSPD,
  matAdd,
  matMul,
  matScale,
  matSub,
  matVec,
  sub,
  symmetrize,
  transpose,
  type Mat,
  type Vec,
} from './linalg';

export type RegimeId = 'cooperative' | 'inflation' | 'conflict' | 'stagnation';

export interface View {
  /** Portfolio picks: positive = long, negative = short. Relative views sum to 0. */
  picks: Partial<Record<Ticker, number>>;
  /** Annualised return the view asserts for pᵀr. */
  q: number;
  /** Confidence in (0, 1). */
  confidence: number;
  label: string;
}

export interface Regime {
  id: RegimeId;
  name: string;
  shortName: string;
  summary: string;
  views: View[];
}

export const REGIMES: readonly Regime[] = [
  {
    id: 'cooperative',
    name: 'Cooperative Global Growth',
    shortName: 'Cooperative',
    summary:
      'Open trade, synchronised expansion, low political risk premia. Risk assets and EM lead; hedges earn little.',
    views: [
      { picks: { EEM: 1, SPY: -1 }, q: 0.02, confidence: 0.55, label: 'EM outperforms US by 200bp' },
      { picks: { EFA: 1, SPY: -1 }, q: 0.01, confidence: 0.45, label: 'Developed ex-US beats US by 100bp' },
      { picks: { GLD: 1 }, q: 0.03, confidence: 0.55, label: 'Gold returns 3% (hedge premium fades)' },
      { picks: { DBC: 1 }, q: 0.04, confidence: 0.45, label: 'Commodities return 4%' },
      { picks: { IEF: 1 }, q: 0.035, confidence: 0.4, label: 'Treasuries return 3.5%' },
    ],
  },
  {
    id: 'inflation',
    name: 'High Inflation / Resource Nationalism',
    shortName: 'Inflation',
    summary:
      'Export controls and cartelised supply keep prices elevated. Real assets and inflation-linked bonds lead; nominal duration suffers.',
    views: [
      { picks: { DBC: 1 }, q: 0.09, confidence: 0.65, label: 'Commodities return 9%' },
      { picks: { TIP: 1, IEF: -1 }, q: 0.025, confidence: 0.7, label: 'TIPS beat Treasuries by 250bp' },
      { picks: { GLD: 1 }, q: 0.07, confidence: 0.6, label: 'Gold returns 7%' },
      { picks: { SPY: 1 }, q: 0.05, confidence: 0.5, label: 'US equities return 5% (margin squeeze)' },
      { picks: { EEM: 1, EFA: -1 }, q: 0.015, confidence: 0.45, label: 'Resource-heavy EM beats DM ex-US by 150bp' },
      { picks: { IEF: 1 }, q: 0.02, confidence: 0.55, label: 'Treasuries return 2%' },
    ],
  },
  {
    id: 'conflict',
    name: 'Geopolitical Fracturing / Conflict',
    shortName: 'Conflict',
    summary:
      'Bloc formation, sanctions and kinetic risk. Gold and energy spike, US assets attract safe-haven flows, EM and Europe de-rate.',
    views: [
      { picks: { GLD: 1 }, q: 0.1, confidence: 0.75, label: 'Gold returns 10% (safe-haven bid)' },
      { picks: { SPY: 1, EFA: -1 }, q: 0.03, confidence: 0.65, label: 'US beats Europe/Japan by 300bp' },
      { picks: { EEM: 1 }, q: 0.015, confidence: 0.65, label: 'EM returns 1.5% (sanctions, capital flight)' },
      { picks: { DBC: 1 }, q: 0.085, confidence: 0.6, label: 'Energy-led commodities return 8.5%' },
      { picks: { IEF: 1 }, q: 0.045, confidence: 0.55, label: 'Treasuries return 4.5% (flight to quality)' },
      { picks: { EFA: 1 }, q: 0.03, confidence: 0.55, label: 'Developed ex-US returns 3%' },
    ],
  },
  {
    id: 'stagnation',
    name: 'Disinflationary Stagnation',
    shortName: 'Stagnation',
    summary:
      'Demographic drag, deleveraging and falling real rates. Duration wins, commodities lose their bid, equities grind.',
    views: [
      { picks: { IEF: 1 }, q: 0.058, confidence: 0.7, label: 'Treasuries return 5.8% (rate cuts)' },
      { picks: { SPY: 1 }, q: 0.045, confidence: 0.55, label: 'US equities return 4.5%' },
      { picks: { EEM: 1 }, q: 0.03, confidence: 0.55, label: 'EM returns 3% (weak global demand)' },
      { picks: { DBC: 1 }, q: 0.0, confidence: 0.6, label: 'Commodities return 0%' },
      { picks: { GLD: 1 }, q: 0.04, confidence: 0.45, label: 'Gold returns 4% (real rates fall)' },
      { picks: { TIP: 1, IEF: -1 }, q: -0.012, confidence: 0.55, label: 'TIPS lag Treasuries by 120bp' },
    ],
  },
];

export const REGIME_BY_ID: Record<RegimeId, Regime> = Object.fromEntries(
  REGIMES.map((r) => [r.id, r]),
) as Record<RegimeId, Regime>;

/** Prior scaling τ: how uncertain the equilibrium is relative to Σ. */
export const TAU = 0.05;

/** Equity basket used by the sentiment view. */
const EQUITY_BASKET: Partial<Record<Ticker, number>> = { SPY: 0.6, EFA: 0.25, EEM: 0.15 };

export interface AppliedView {
  label: string;
  /** Effective view return after θ scaling. */
  q: number;
  /** Equilibrium-implied return for the same pick vector (PΠ). */
  prior: number;
  /** Effective confidence after θ scaling. */
  confidence: number;
  /** Diagonal Ω entry. */
  omega: number;
  isSentiment: boolean;
}

export interface BLInputs {
  regime: RegimeId;
  /** Geopolitical inertia θ ∈ [0, 1]. */
  theta: number;
  /** Equity sentiment ∈ [-1, 1]; 0 disables the sentiment view. */
  sentiment: number;
}

export interface BLResult {
  mu: Vec;
  sigma: Mat;
  prior: Vec;
  views: AppliedView[];
  P: Mat;
  Q: Vec;
  omega: Vec;
}

const clamp = (x: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, x));

const pickVector = (picks: Partial<Record<Ticker, number>>): Vec => {
  const p = new Array<number>(N_ASSETS).fill(0);
  for (const t of TICKERS) {
    const v = picks[t];
    if (v) p[INDEX[t]] = v;
  }
  return p;
};

/**
 * Build P, Q, Ω for a regime at inertia θ with optional sentiment, then
 * compute the posterior. Pure and deterministic; ~0.1ms at n = 8.
 */
export function blackLitterman({ regime, theta, sentiment }: BLInputs): BLResult {
  const t = clamp(theta, 0, 1);
  // θ scales structural conviction: view size and certainty both shrink as
  // θ → 0, so the posterior slides back onto the cyclical prior.
  const magnitude = 0.25 + 0.75 * t;
  const certainty = 0.2 + 0.8 * t;

  const P: Mat = [];
  const Q: Vec = [];
  const omega: Vec = [];
  const applied: AppliedView[] = [];

  const tauSigma = matScale(SIGMA, TAU);

  const pushView = (
    picks: Partial<Record<Ticker, number>>,
    q: number,
    conf: number,
    label: string,
    isSentiment: boolean,
  ) => {
    const p = pickVector(picks);
    const prior = dot(p, PI);
    // Ω_k = τ·pΣpᵀ·(1−c)/c — the He-Litterman variance at c = 0.5, tighter
    // with more confidence, looser with less.
    const pSp = dot(p, matVec(tauSigma, p));
    const om = Math.max(pSp * ((1 - conf) / conf), 1e-10);
    P.push(p);
    Q.push(q);
    omega.push(om);
    applied.push({ label, q, prior, confidence: conf, omega: om, isSentiment });
  };

  for (const v of REGIME_BY_ID[regime].views) {
    const prior = dot(pickVector(v.picks), PI);
    const q = prior + magnitude * (v.q - prior);
    const conf = clamp(v.confidence * certainty, 0.03, 0.97);
    pushView(v.picks, q, conf, v.label, false);
  }

  const s = clamp(sentiment, -1, 1);
  if (Math.abs(s) > 0.01) {
    // ±400bp at full conviction. Raw confidence rises with |s| and is not
    // θ-scaled: sentiment is a cyclical view, not a structural one.
    const prior = dot(pickVector(EQUITY_BASKET), PI);
    const q = prior + 0.04 * s;
    const conf = clamp(0.2 + 0.6 * Math.abs(s), 0.03, 0.97);
    const bp = Math.round(s * 400);
    pushView(
      EQUITY_BASKET,
      q,
      conf,
      `${s > 0 ? 'Bullish' : 'Bearish'} equity sentiment (${bp > 0 ? '+' : ''}${bp}bp)`,
      true,
    );
  }

  if (P.length === 0) {
    return { mu: [...PI], sigma: matAdd(SIGMA, tauSigma), prior: [...PI], views: [], P, Q, omega };
  }

  const Pt = transpose(P);
  const tauSigmaPt = matMul(tauSigma, Pt); // n×k
  const PtauSigmaPt = matMul(P, tauSigmaPt); // k×k
  const M = symmetrize(PtauSigmaPt.map((row, i) => row.map((x, j) => x + (i === j ? omega[i] : 0))));
  const Minv = invertSPD(M);

  const gain = matMul(tauSigmaPt, Minv); // n×k
  const innovation = sub(Q, matVec(P, PI)); // Q − PΠ
  const mu = PI.map((pi, i) => pi + dot(gain[i], innovation));

  // Posterior covariance of the mean: τΣ − τΣPᵀ M⁻¹ PτΣ; add to Σ for the
  // predictive covariance of returns.
  const reduction = matMul(gain, matMul(P, tauSigma));
  const sigma = symmetrize(matAdd(SIGMA, matSub(tauSigma, reduction)));

  return { mu, sigma, prior: [...PI], views: applied, P, Q, omega };
}

src/lib/optimizer/engine.ts:
/**
 * Orchestration: inputs → Black-Litterman posterior → CVaR-optimal weights →
 * risk HUD numbers, and separately → Monte Carlo fan.
 *
 * The allocation stage is the hot path (every slider tick) and runs in a few
 * milliseconds. The simulation stage is heavier and is meant to run on a
 * deferred value so dragging never stalls.
 */

import { blackLitterman, type BLResult, type RegimeId } from './blackLitterman';
import { dot, quadForm, type Mat, type Vec } from './linalg';
import { simulate, type SimulationResult } from './monteCarlo';
import { maxAttainableReturn, minimizeCvar, portfolioStats, type PortfolioStats } from './solver';
import { RISK_FREE, SIGMA, WEIGHT_CAP, W_6040, W_CASH } from './universe';

export type RiskProfile = 'conservative' | 'moderate' | 'aggressive' | 'hedged';

export interface ProfileSpec {
  id: RiskProfile;
  name: string;
  summary: string;
  /** Position of the return target between the min-CVaR and max-return portfolios. */
  fraction: number;
  robust: boolean;
}

export const PROFILES: readonly ProfileSpec[] = [
  { id: 'conservative', name: 'Conservative', summary: 'Capital preservation; near the minimum-CVaR frontier point.', fraction: 0.15, robust: false },
  { id: 'moderate', name: 'Moderate', summary: 'Balanced growth with a bounded tail.', fraction: 0.45, robust: false },
  { id: 'aggressive', name: 'Aggressive', summary: 'Return-seeking; accepts a fatter left tail.', fraction: 0.8, robust: false },
  { id: 'hedged', name: 'Geopolitical-Hedged', summary: 'Minimax: optimises the worse of the current and conflict regimes.', fraction: 0.4, robust: true },
];

export const PROFILE_BY_ID: Record<RiskProfile, ProfileSpec> = Object.fromEntries(
  PROFILES.map((p) => [p.id, p]),
) as Record<RiskProfile, ProfileSpec>;

export interface OptimizerInputs {
  initialCapital: number;
  monthlyContribution: number;
  horizonYears: number;
  profile: RiskProfile;
  regime: RegimeId;
  /** Geopolitical inertia θ ∈ [0, 1]. */
  theta: number;
  /** Equity sentiment ∈ [-1, 1]. */
  sentiment: number;
}

export const DEFAULT_INPUTS: OptimizerInputs = {
  initialCapital: 250_000,
  monthlyContribution: 2_000,
  horizonYears: 15,
  profile: 'moderate',
  regime: 'conflict',
  theta: 0.6,
  sentiment: 0,
};

export interface AllocationResult {
  inputs: OptimizerInputs;
  bl: BLResult;
  weights: Vec;
  solve: { lambda: number; iterations: number; feasible: boolean; target: number };
  /** Return range available to the profile selector. */
  frontier: { minCvarReturn: number; maxReturn: number };
  stats: { adaptive: PortfolioStats; benchmark: PortfolioStats; cash: PortfolioStats };
  /** Prior (equilibrium) stats of the same weights, for the "posterior shift" readout. */
  priorStats: { adaptive: PortfolioStats; benchmark: PortfolioStats };
  resilience: {
    /** Expected-return edge over 60/40 if the world snaps to full conflict, in bp. */
    alphaBps: number;
    /** CVaR improvement over 60/40 under full conflict, in bp (positive = smaller tail loss). */
    cvarEdgeBps: number;
    adaptive: PortfolioStats;
    benchmark: PortfolioStats;
  };
  /** 3×3 correlation between adaptive / 60-40 / cash under Σ_BL. */
  strategyCorrelation: Mat;
  timingMs: number;
}

const now = () => (typeof performance !== 'undefined' ? performance.now() : Date.now());

export function computeAllocation(inputs: OptimizerInputs): AllocationResult {
  const t0 = now();
  const bl = blackLitterman({ regime: inputs.regime, theta: inputs.theta, sentiment: inputs.sentiment });
  const model = { mu: bl.mu, sigma: bl.sigma };
  const profile = PROFILE_BY_ID[inputs.profile];

  // The conflict posterior at full inertia is the stress world used by both
  // the hedged profile's minimax objective and the resilience alpha.
  const conflict = blackLitterman({ regime: 'conflict', theta: 1, sentiment: 0 });
  const conflictModel = { mu: conflict.mu, sigma: conflict.sigma };
  const robustModel = profile.robust ? conflictModel : undefined;

  // Anchor the return range: minimum-CVaR return (λ = 0) to max attainable.
  const minCvar = minimizeCvar({ model, robustModel, targetReturn: -1, cap: WEIGHT_CAP });
  const { ret: maxReturn } = maxAttainableReturn(bl.mu, WEIGHT_CAP);
  const minCvarReturn = minCvar.ret;
  const target = minCvarReturn + profile.fraction * Math.max(maxReturn - minCvarReturn, 0);

  const solved = minimizeCvar({ model, robustModel, targetReturn: target, cap: WEIGHT_CAP, initial: minCvar.weights });
  const weights = solved.weights.map((w) => (w < 5e-4 ? 0 : w));
  const sum = weights.reduce((a, b) => a + b, 0);
  for (let i = 0; i < weights.length; i++) weights[i] /= sum;

  const stats = {
    adaptive: portfolioStats(weights, bl.mu, bl.sigma, RISK_FREE),
    benchmark: portfolioStats(W_6040, bl.mu, bl.sigma, RISK_FREE),
    cash: portfolioStats(W_CASH, bl.mu, bl.sigma, RISK_FREE),
  };
  const priorStats = {
    adaptive: portfolioStats(weights, bl.prior, SIGMA, RISK_FREE),
    benchmark: portfolioStats(W_6040, bl.prior, SIGMA, RISK_FREE),
  };

  const resAdaptive = portfolioStats(weights, conflict.mu, conflict.sigma, RISK_FREE);
  const resBenchmark = portfolioStats(W_6040, conflict.mu, conflict.sigma, RISK_FREE);
  const resilience = {
    alphaBps: (resAdaptive.ret - resBenchmark.ret) * 1e4,
    cvarEdgeBps: (resBenchmark.cvar - resAdaptive.cvar) * 1e4,
    adaptive: resAdaptive,
    benchmark: resBenchmark,
  };

  const ws = [weights, W_6040, W_CASH];
  const vols = ws.map((w) => Math.sqrt(Math.max(quadForm(bl.sigma, w), 1e-16)));
  const strategyCorrelation = ws.map((wi, i) =>
    ws.map((wj, j) => {
      if (i === j) return 1;
      let cov = 0;
      for (let a = 0; a < wi.length; a++) {
        if (wi[a] === 0) continue;
        for (let b = 0; b < wj.length; b++) cov += wi[a] * bl.sigma[a][b] * wj[b];
      }
      return Math.max(-0.999, Math.min(0.999, cov / (vols[i] * vols[j])));
    }),
  );

  return {
    inputs,
    bl,
    weights,
    solve: { lambda: solved.lambda, iterations: solved.iterations + minCvar.iterations, feasible: solved.feasible, target: solved.target },
    frontier: { minCvarReturn, maxReturn },
    stats,
    priorStats,
    resilience,
    strategyCorrelation,
    timingMs: now() - t0,
  };
}

export interface SimulationOutput extends SimulationResult {
  timingMs: number;
}

export function computeSimulation(alloc: AllocationResult): SimulationOutput {
  const t0 = now();
  const { inputs, stats, strategyCorrelation } = alloc;
  const result = simulate({
    strategies: [
      { key: 'adaptive', label: 'Adaptive Geopolitical', mu: stats.adaptive.ret, vol: stats.adaptive.vol },
      { key: 'benchmark', label: 'Static 60/40', mu: stats.benchmark.ret, vol: stats.benchmark.vol },
      { key: 'cash', label: '100% T-Bills', mu: stats.cash.ret, vol: stats.cash.vol },
    ],
    correlation: strategyCorrelation,
    initialCapital: inputs.initialCapital,
    monthlyContribution: inputs.monthlyContribution,
    horizonYears: inputs.horizonYears,
    paths: 1000,
    seed: 0x5eed,
    riskFree: RISK_FREE,
  });
  return { ...result, timingMs: now() - t0 };
}

/** Convenience: dot product exported for UI-side derived numbers. */
export { dot };

src/lib/optimizer/linalg.ts:
/**
 * Dense linear algebra for small (n ≤ ~16) systems.
 *
 * Everything the optimizer needs is here: products, transposes, a Cholesky
 * factorisation with jitter for near-singular SPD matrices, and a pivoted
 * Gauss-Jordan inverse as the general fallback. Plain number[][] keeps the
 * code readable; at n = 8 the difference to typed arrays is noise.
 */

export type Vec = number[];
export type Mat = number[][];

export const zeros = (n: number): Vec => new Array<number>(n).fill(0);

export const zerosMat = (rows: number, cols: number): Mat =>
  Array.from({ length: rows }, () => zeros(cols));

export const identity = (n: number): Mat =>
  Array.from({ length: n }, (_, i) => {
    const row = zeros(n);
    row[i] = 1;
    return row;
  });

export const diag = (values: Vec): Mat =>
  values.map((v, i) => {
    const row = zeros(values.length);
    row[i] = v;
    return row;
  });

export const transpose = (a: Mat): Mat => {
  if (a.length === 0) return [];
  return a[0].map((_, j) => a.map((row) => row[j]));
};

export const matMul = (a: Mat, b: Mat): Mat => {
  const rows = a.length;
  const inner = b.length;
  const cols = inner === 0 ? 0 : b[0].length;
  const out = zerosMat(rows, cols);
  for (let i = 0; i < rows; i++) {
    const ai = a[i];
    const oi = out[i];
    for (let k = 0; k < inner; k++) {
      const aik = ai[k];
      if (aik === 0) continue;
      const bk = b[k];
      for (let j = 0; j < cols; j++) oi[j] += aik * bk[j];
    }
  }
  return out;
};

export const matVec = (a: Mat, v: Vec): Vec =>
  a.map((row) => {
    let s = 0;
    for (let j = 0; j < row.length; j++) s += row[j] * v[j];
    return s;
  });

export const dot = (a: Vec, b: Vec): number => {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s;
};

export const add = (a: Vec, b: Vec): Vec => a.map((x, i) => x + b[i]);
export const sub = (a: Vec, b: Vec): Vec => a.map((x, i) => x - b[i]);
export const scale = (a: Vec, k: number): Vec => a.map((x) => x * k);

export const matAdd = (a: Mat, b: Mat): Mat => a.map((row, i) => row.map((x, j) => x + b[i][j]));
export const matSub = (a: Mat, b: Mat): Mat => a.map((row, i) => row.map((x, j) => x - b[i][j]));
export const matScale = (a: Mat, k: number): Mat => a.map((row) => row.map((x) => x * k));

/** wᵀ A w */
export const quadForm = (a: Mat, w: Vec): number => {
  let s = 0;
  for (let i = 0; i < w.length; i++) {
    const wi = w[i];
    if (wi === 0) continue;
    const row = a[i];
    for (let j = 0; j < w.length; j++) s += wi * row[j] * w[j];
  }
  return s;
};

/**
 * Cholesky factor L with A = L Lᵀ. If the matrix is not numerically SPD the
 * diagonal is nudged (jitter) until it is; the nudge is reported so callers
 * can decide whether to care.
 */
export const cholesky = (a: Mat): { L: Mat; jitter: number } => {
  const n = a.length;
  let jitter = 0;
  for (let attempt = 0; attempt < 12; attempt++) {
    const L = zerosMat(n, n);
    let ok = true;
    for (let i = 0; i < n && ok; i++) {
      for (let j = 0; j <= i; j++) {
        let s = a[i][j] + (i === j ? jitter : 0);
        for (let k = 0; k < j; k++) s -= L[i][k] * L[j][k];
        if (i === j) {
          if (s <= 1e-14) {
            ok = false;
            break;
          }
          L[i][i] = Math.sqrt(s);
        } else {
          L[i][j] = s / L[j][j];
        }
      }
    }
    if (ok) return { L, jitter };
    jitter = jitter === 0 ? 1e-10 : jitter * 10;
  }
  throw new Error('cholesky: matrix is not positive definite');
};

/** Solve A x = b for SPD A using its Cholesky factor. */
export const choleskySolve = (L: Mat, b: Vec): Vec => {
  const n = L.length;
  const y = zeros(n);
  for (let i = 0; i < n; i++) {
    let s = b[i];
    for (let k = 0; k < i; k++) s -= L[i][k] * y[k];
    y[i] = s / L[i][i];
  }
  const x = zeros(n);
  for (let i = n - 1; i >= 0; i--) {
    let s = y[i];
    for (let k = i + 1; k < n; k++) s -= L[k][i] * x[k];
    x[i] = s / L[i][i];
  }
  return x;
};

/** Inverse of a general square matrix by Gauss-Jordan with partial pivoting. */
export const invert = (a: Mat): Mat => {
  const n = a.length;
  const m = a.map((row, i) => [...row, ...identity(n)[i]]);
  for (let col = 0; col < n; col++) {
    let pivot = col;
    for (let r = col + 1; r < n; r++) if (Math.abs(m[r][col]) > Math.abs(m[pivot][col])) pivot = r;
    if (Math.abs(m[pivot][col]) < 1e-14) throw new Error('invert: singular matrix');
    if (pivot !== col) [m[col], m[pivot]] = [m[pivot], m[col]];
    const p = m[col][col];
    for (let j = 0; j < 2 * n; j++) m[col][j] /= p;
    for (let r = 0; r < n; r++) {
      if (r === col) continue;
      const f = m[r][col];
      if (f === 0) continue;
      for (let j = 0; j < 2 * n; j++) m[r][j] -= f * m[col][j];
    }
  }
  return m.map((row) => row.slice(n));
};

/** Inverse of an SPD matrix through its Cholesky factor (falls back to Gauss-Jordan). */
export const invertSPD = (a: Mat): Mat => {
  try {
    const { L } = cholesky(a);
    const n = a.length;
    const cols = identity(n).map((e) => choleskySolve(L, e));
    return transpose(cols);
  } catch {
    return invert(a);
  }
};

/** Force exact symmetry after a chain of products that may have drifted. */
export const symmetrize = (a: Mat): Mat =>
  a.map((row, i) => row.map((x, j) => 0.5 * (x + a[j][i])));

